def _apply_trail_sl(ver: int, t: dict, price: float):
    """Fixed 50/50 rule, two phases:
    Phase 1 (pre-TP1): once price reaches the halfway point to TP1, move SL to
    the halfway point between the original SL and entry.
    Phase 2 (post-TP1): SL sits at breakeven after TP1 — once price reaches the
    halfway point between that breakeven SL and TP2, move SL up to that point,
    locking in more than just breakeven before TP2 itself hits.
    Each phase runs once (trail_sl_moved / trail_sl2_moved guards it), and each
    replaces the OTHER phase's still-open trailing message (deleted at TP1 hit
    for phase 1's, and at TP2/SL close for phase 2's — see _delete_trail_sl_messages).
    ver: 1=Scan1, 2=Scan2, 3=Demo1, 4=Demo2 — ct.update_scan_sl() looks the symbol
    up across all slot prefixes (including demo1/demo2), so this also moves any
    real copy-user SL that's mirroring a demo trade."""
    enabled = {1: TRAIL_SL_SCAN1, 2: TRAIL_SL_SCAN2, 3: TRAIL_SL_DEMO1, 4: TRAIL_SL_DEMO2}.get(ver, False)
    if not enabled:
        return
    sig = t["signal"]; tag = f"S{ver}" if ver <= 2 else f"TS{ver - 2}"
    if not t.get("tp1_hit"):
        if t.get("trail_sl_moved"):
            return
        entry = t["entry"]; tp1 = t["tp1"]
        orig_sl = t.get("trail_sl_orig", t["sl"])
        t["trail_sl_orig"] = orig_sl
        midpoint_price = (entry + tp1) / 2
        hit = (sig == "BUY" and price >= midpoint_price) or (sig == "SELL" and price <= midpoint_price)
        if not hit:
            return
        new_sl = (orig_sl + entry) / 2
        t["sl"] = new_sl
        t["trail_sl_moved"] = True
        ct.update_scan_sl(t["symbol"], new_sl)
        save_state()
        _msg = (
            f"🛡️ <b>Trailing SL — #{t['symbol']}</b>  {tag}\n\n"
            f"Price reached halfway to TP1 — SL moved <code>{orig_sl:,.4g}</code> → <code>{new_sl:,.4g}</code> to lock in more capital.")
        _locked_msg = (
            f"🛡️ <b>Trailing SL — #{t['symbol']}</b>  {tag}\n\n"
            f"Price reached halfway to TP1 — SL moved BE to lock in more capital.")
        _trail_ids = send_lifecycle_reply(_msg, t.get("reply_map"), include_ch2=False,
            tier_routed=bool(t.get("tier_routed")), share_free=t.get("share_free", True), locked_text=_locked_msg)
        t["trail_sl_msg_ids"] = _trail_ids or {}
        for _k, _v in (_trail_ids or {}).items():
            if _k.startswith("free:"): _track_free_sl(t.get("sig_id",""), _k.split(":", 1)[1], "trailing_mid", _v)
    else:
        if t.get("trail_sl2_moved"):
            return
        be_sl = t["sl"]; tp2 = t["tp2"]
        midpoint2 = (be_sl + tp2) / 2
        hit2 = (sig == "BUY" and price >= midpoint2) or (sig == "SELL" and price <= midpoint2)
        if not hit2:
            return
        t["sl"] = midpoint2
        t["trail_sl2_moved"] = True
        ct.update_scan_sl(t["symbol"], midpoint2)
        save_state()
        _msg = (
            f"🛡️ <b>Trailing SL (Post-TP1) — #{t['symbol']}</b>  {tag}\n\n"
            f"Price reached halfway to TP2 — SL moved <code>{be_sl:,.4g}</code> → <code>{midpoint2:,.4g}</code> to lock in more profit.")
        _locked_msg = (
            f"🛡️ <b>Trailing SL (Post-TP1) — #{t['symbol']}</b>  {tag}\n\n"
            f"Price reached halfway to TP2 — SL moved up to lock in more profit.")
        _trail_ids = send_lifecycle_reply(_msg, t.get("reply_map"), include_ch2=False,
            tier_routed=bool(t.get("tier_routed")), share_free=t.get("share_free", True), locked_text=_locked_msg)
        t["trail_sl_msg_ids"] = _trail_ids or {}
        for _k, _v in (_trail_ids or {}).items():
            if _k.startswith("free:"): _track_free_sl(t.get("sig_id",""), _k.split(":", 1)[1], "trailing_mid2", _v)

def _apply_trail_sl_btc(price: float):
    if not TRAIL_SL_BTC:
        return
    sig = active_trade["signal"]
    if not active_trade.get("tp1_hit"):
        if active_trade.get("trail_sl_moved"):
            return
        entry = active_trade["entry"]; tp1 = active_trade["tp1"]
        orig_sl = active_trade.get("trail_sl_orig", active_trade["sl"])
        active_trade["trail_sl_orig"] = orig_sl
        midpoint_price = (entry + tp1) / 2
        hit = (sig == "BUY" and price >= midpoint_price) or (sig == "SELL" and price <= midpoint_price)
        if not hit:
            return
        new_sl = (orig_sl + entry) / 2
        active_trade["sl"] = new_sl
        active_trade["trail_sl_moved"] = True
        ct.on_update_sl(new_sl)
        save_active_trade()
        _msg = (
            f"🛡️ <b>Trailing SL — BTC</b>\n\n"
            f"Price reached halfway to TP1 — SL moved <code>{orig_sl:,.0f}</code> → <code>{new_sl:,.0f}</code> to lock in more capital.")
        _locked_msg = (
            f"🛡️ <b>Trailing SL — BTC</b>\n\n"
            f"Price reached halfway to TP1 — SL moved BE to lock in more capital.")
        _trail_ids = send_lifecycle_reply(_msg, active_trade.get("reply_map"), include_ch2=False,
            tier_routed=True, share_free=active_trade.get("share_free", True), locked_text=_locked_msg)
        active_trade["trail_sl_msg_ids"] = _trail_ids or {}
        for _k, _v in (_trail_ids or {}).items():
            if _k.startswith("free:"): _track_free_sl(active_trade.get("sig_id",""), _k.split(":", 1)[1], "trailing_mid", _v)
    else:
        if active_trade.get("trail_sl2_moved"):
            return
        be_sl = active_trade["sl"]; tp2 = active_trade["tp2"]
        midpoint2 = (be_sl + tp2) / 2
        hit2 = (sig == "BUY" and price >= midpoint2) or (sig == "SELL" and price <= midpoint2)
        if not hit2:
            return
        active_trade["sl"] = midpoint2
        active_trade["trail_sl2_moved"] = True
        ct.on_update_sl(midpoint2)
        save_active_trade()
        _msg = (
            f"🛡️ <b>Trailing SL (Post-TP1) — BTC</b>\n\n"
            f"Price reached halfway to TP2 — SL moved <code>{be_sl:,.0f}</code> → <code>{midpoint2:,.0f}</code> to lock in more profit.")
        _locked_msg = (
            f"🛡️ <b>Trailing SL (Post-TP1) — BTC</b>\n\n"
            f"Price reached halfway to TP2 — SL moved up to lock in more profit.")
        _trail_ids = send_lifecycle_reply(_msg, active_trade.get("reply_map"), include_ch2=False,
            tier_routed=True, share_free=active_trade.get("share_free", True), locked_text=_locked_msg)
        active_trade["trail_sl_msg_ids"] = _trail_ids or {}
        for _k, _v in (_trail_ids or {}).items():
            if _k.startswith("free:"): _track_free_sl(active_trade.get("sig_id",""), _k.split(":", 1)[1], "trailing_mid2", _v)
    for _k, _v in (_trail_ids or {}).items():
        if _k.startswith("free:"): _track_free_sl(active_trade.get("sig_id",""), _k.split(":", 1)[1], "trailing_mid", _v)

def _delete_trail_sl_messages(t: dict):
    """TP1 hit makes the earlier 'Trailing SL moved to X' note stale (SL is
    about to move again, to breakeven) — delete it from every channel it was
    posted to instead of leaving an outdated message sitting in the feed."""
    _ids = t.get("trail_sl_msg_ids") or {}
    if not _ids:
        return
    for _k, _mid in _ids.items():
        if _k == "ch1": _cid = TELEGRAM_CHANNEL_ID
        elif _k == "ch2": _cid = TELEGRAM_CHANNEL_ID_2
        else: _cid = _k.split(":", 1)[1]
        if not _cid: continue
        try:
            requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/deleteMessage",
                json={"chat_id": _cid, "message_id": _mid}, timeout=10)
        except Exception as e:
            print(f"  [TRAIL SL] delete msg error: {e}")
    t["trail_sl_msg_ids"] = {}
# ─── VIP / Free channels + user tiers ──────────────────────────────────────
CHANNELS: list = []  # [{"id": str, "tier": "vip"/"free", "label": str}, ...] — any number of each
FREE_SIGNAL_DAILY_LIMIT = 40   # % of each day's verified/special signals also shared to Free (0-100)
_free_signal_tracker = {"date": "", "total": 0, "shared": 0}  # resets automatically when the IST date rolls over

def _daily_verified_slot_count() -> int:
    """Fixed count of the day's SCHEDULED 'verified' slot times across
    Scan1/Scan2/TS1/TS2 (admin-configured special times minus the no-copy
    exclusions) — known upfront from settings, independent of how many of
    those slots actually fire a real signal vs. 'no trade found' that day."""
    return sum(len(_SCAN_SPECIAL.get(k, set())) - len(_SCAN_SPECIAL_NO_COPY.get(k, set()))
               for k in ("scan1", "scan2", "test1", "test2"))

def _save_free_tracker():
    """Persists _free_signal_tracker to local disk AND the central store — same
    fix as _save_daily_buckets(): a pure in-memory counter silently resets to
    0/0 on every Railway redeploy (and, in the multi-server setup, is never
    shared between the standby and active instances), which is exactly why the
    Free Channel Share % screen kept showing 0/0 shared even while signals
    were actively being posted to Free from whichever process fired them."""
    try:
        with open(os.path.join(DATA_DIR, "free_signal_tracker.json"), "w") as f:
            json.dump(_free_signal_tracker, f)
    except Exception as e:
        print(f"[FREE TRACKER] local save error: {e}")
    # Active-server gate — see save_settings()'s comment: a standby/abandoned
    # server keeps running this same loop with its own local counters, and
    # would otherwise silently clobber the active server's real numbers.
    if CLEXER_API_URL and is_active_server():
        try:
            _kv_push("free_signal_tracker", _free_signal_tracker)
        except Exception as e:
            print(f"[FREE TRACKER] central push error: {e}")

def _load_free_tracker():
    global _free_signal_tracker
    try:
        d = None
        path = os.path.join(DATA_DIR, "free_signal_tracker.json")
        if CLEXER_API_URL:
            r = _central_get("/kv/free_signal_tracker")
            if r is not None and r.ok:
                d = _kv_pick_newer(path, r.json(), "FREE TRACKER")
        if d is None and os.path.exists(path):
            with open(path) as f:
                d = json.load(f)
        if d is not None:
            _free_signal_tracker = {"date": d.get("date",""), "total": d.get("total",0), "shared": d.get("shared",0)}
            print(f"[FREE TRACKER] Restored {_free_signal_tracker}")
    except Exception as e:
        print(f"[FREE TRACKER] load error: {e}")

def _channels_by_tier(tier: str) -> list:
    ids = [c["id"] for c in CHANNELS if c.get("tier") == tier and c.get("id") and not c.get("paused")]
    if tier == "vip" and TELEGRAM_CHANNEL_ID_2 and not channel_paused.get("2"):
        ids.append(TELEGRAM_CHANNEL_ID_2)
    return ids

def _in_free_window() -> bool:
    now = datetime.now(timezone.utc) + IST
    return 6 <= now.hour < 23  # 06:00–23:00 IST

def _free_quota_available() -> bool:
    """FREE_SIGNAL_DAILY_LIMIT rule: that % of the day's SCHEDULED verified
    slots (_daily_verified_slot_count() -- a fixed, known-upfront number from
    the admin's special-time config, e.g. 11) sets a flat daily quota (e.g.
    40% of 11 -> 4). Real verified fires share back-to-back, in order, from
    the start of the day: #1 through #4 share, #5 through #11 lock -- no
    gaps in between, no live ratio re-check. Once `shared` hits the quota
    nothing else shares that day, however many more verified fires happen."""
    global _free_signal_tracker
    now = datetime.now(timezone.utc) + IST
    today = now.strftime("%Y-%m-%d")
    if _free_signal_tracker.get("date") != today:
        print(f"[FREE QUOTA] day rollover - was {_free_signal_tracker}, resetting for {today}")
        _free_signal_tracker = {"date": today, "total": 0, "shared": 0}
    _free_signal_tracker["total"] += 1
    _save_free_tracker()
    _quota = round(_daily_verified_slot_count() * (FREE_SIGNAL_DAILY_LIMIT / 100.0))
    _win = _in_free_window()
    _decision = _win and (_free_signal_tracker["shared"] < _quota)
    print(f"[FREE QUOTA] total={_free_signal_tracker['total']} shared={_free_signal_tracker['shared']} "
          f"quota={_quota} in_window={_win} -> {'SHARE' if _decision else 'LOCK'}")
    return _decision

def _consume_free_quota():
    _free_signal_tracker["shared"] = _free_signal_tracker.get("shared", 0) + 1
    print(f"[FREE QUOTA] consumed -> shared now {_free_signal_tracker['shared']}")
    _save_free_tracker()

_BOT_USERNAME = None

def _get_bot_username():
    global _BOT_USERNAME
    if _BOT_USERNAME:
        return _BOT_USERNAME
    try:
        r = requests.get(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/getMe", timeout=10)
        rj = r.json()
        if rj.get("ok"):
            _BOT_USERNAME = rj["result"]["username"]
    except Exception as e:
        print(f"  [GETME ERROR] {e}")
    return _BOT_USERNAME

def _send_via_true_forward(text: str, dest_chat_id, tag: str, with_bot_button: bool = False, protect: bool = False) -> bool:
    """Sends via plain sendMessage. NOTE: this used to stage-then-forwardMessage
    to "preserve" premium/custom emoji — that assumption was wrong. /testreply
    proved the opposite empirically: forwardMessage strips premium emoji, while
    plain sendMessage (with the <tg-emoji> entities _apply_premium_emojis already
    wrapped the text in, by the time it reaches here) renders them correctly.
    Kept the same name/signature so every existing caller needed no changes.
    If with_bot_button, sends a small follow-up message with an 'Open Bot' link.
    protect=True sets protect_content, blocking forward/save — for VIP-only sends."""
    base = f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}"
    _payload = {"chat_id": dest_chat_id, "text": text, "parse_mode": "HTML",
                "disable_web_page_preview": True}
    if protect:
        _payload["protect_content"] = True
    try:
        r = requests.post(f"{base}/sendMessage", json=_payload, timeout=10)
        rj = r.json()
        if not rj.get("ok"):
            print(f"  [SEND] {tag} {dest_chat_id} rejected: {rj.get('description')}")
            return False
        if with_bot_button:
            _uname = _get_bot_username()
            if _uname:
                r_btn = requests.post(f"{base}/sendMessage",
                    json={"chat_id": dest_chat_id, "text": "👇 Copy this trade automatically",
                          "reply_markup": {"inline_keyboard": [[
                              {"text": "🤖 Open Bot", "url": f"https://t.me/{_uname}", "style": "primary"}]]}},
                    timeout=10)
                if not r_btn.json().get("ok"):
                    print(f"  [SEND BUTTON] {tag} {dest_chat_id} failed: {r_btn.json().get('description')}")
        return rj.get("result", {}).get("message_id") or True
    except Exception as e:
        print(f"  [SEND] {tag} {dest_chat_id}: {e}")
        return False


def _react_to_message(chat_id, message_id, emoji: str = "🔥"):
    """Bot reacts to its own message with an emoji — used to auto-react to
    TP2 (full win) posts. Silent no-op on failure, same as _pin_message."""
    if not message_id:
        return
    try:
        r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/setMessageReaction",
            json={"chat_id": chat_id, "message_id": message_id,
                  "reaction": [{"type": "emoji", "emoji": emoji}]}, timeout=10)
        if not r.json().get("ok"):
            print(f"  [REACT] {chat_id} msg {message_id} failed: {r.json().get('description')}")
    except Exception as e:
        print(f"  [REACT] {chat_id} msg {message_id}: {e}")

# Each channel type only accepts a fixed, admin-configured set of reactions —
# Telegram silently rejects any emoji outside it (admin request 2026-08-06,
# after every auto-react since the TP2-only days turned out to be silently
# failing on Signal/Free because 🔥 was the only one of our old picks that
# happened to be in ANY of these lists). One emoji per lifecycle event per
# channel type, drawn only from what that channel actually allows:
#   Signal: 🔥 🙏 🍾 🤗      VIP: ❤️‍🔥 🔥 💔 😎      Free: 🔥 ❤️‍🔥 💔 🏆
_REACT_EMOJI_MAP = {
    "entry":        {"ch1": "🙏", "vip": "😎", "free": "❤️‍🔥"},
    "tp1":          {"ch1": "🍾", "vip": "🔥", "free": "🔥"},
    "tp2":          {"ch1": "🔥", "vip": "🔥", "free": "🏆"},
    "sl":           {"ch1": "🙏", "vip": "💔", "free": "💔"},
    "be":           {"ch1": "🤗", "vip": "😎", "free": "❤️‍🔥"},
    "timeout_win":  {"ch1": "🔥", "vip": "🔥", "free": "🏆"},
    "timeout_loss": {"ch1": "🙏", "vip": "💔", "free": "💔"},
}

def _react_to_ids(ids: dict, category: str = "tp2"):
    """Reacts to every destination message_id in a send_lifecycle_reply-style
    ids dict (e.g. {"ch1": mid, "vip:123": mid, "free:456": mid}) — using the
    emoji that specific channel TYPE actually allows for this event category,
    since Signal/VIP/Free each have their own separate allowed-reaction list."""
    _emap = _REACT_EMOJI_MAP.get(category, {})
    for key, mid in (ids or {}).items():
        if key.startswith("vip:"):
            cid, _kind = key.split(":", 1)[1], "vip"
        elif key.startswith("free:"):
            cid, _kind = key.split(":", 1)[1], "free"
        else:  # "ch1" (or any legacy ch2 key) — Signal channel
            cid, _kind = (TELEGRAM_CHANNEL_ID if key == "ch1" else TELEGRAM_CHANNEL_ID_2), "ch1"
        emoji = _emap.get(_kind)
        if cid and mid and emoji:
            _react_to_message(cid, mid, emoji)

# Reply keyboard button label -> command it triggers when tapped. Reply-
# keyboard buttons just send their label as plain text (unlike inline
# buttons, they can't carry a URL or callback_data) — the main message loop
# intercepts these exact strings and dispatches the matching command.
# "Trade Control", "Copy Trade" and "Contact Admin" aren't in here — they need
# special handling (open a menu / show a URL button) instead of a plain command.
_REPLY_KB_CMD_MAP = {
    "📊 Status": "/status",
    "📈 My Trades": "/trade",
    "👑 Get VIP": "/vip",
    "📋 Trade Log": "/tradelog",
    "🧠 AI Gateway": "/aiconfig",
    "👥 Users": "/users",
}

def _reply_keyboard_for_chat(chat_id) -> dict:
    """Persistent reply keyboard, tailored to who's talking to the bot —
    admin, co-admin, VIP user, or free user. Sent on /start."""
    cid_str = str(chat_id)
    if ADMIN_CHAT_ID and cid_str == str(ADMIN_CHAT_ID):
        rows = [["📊 Status", "⏸ Pause/Resume"], ["🧠 AI Gateway", "📋 Trade Log"], ["👥 Users"]]
    elif is_co_admin(chat_id):
        rows = [["🧠 AI Gateway", "🛠 Trade Control"], ["📋 Trade Log", "📊 Status"]]
    else:
        _u = ct._get(cid_str) or {}
        if _u.get("tier") == "vip":
            rows = [["📊 Status", "📈 My Trades"], ["🔄 Copy Trade", "💬 Contact Admin"]]
        else:
            rows = [["📊 Status", "📈 My Trades"], ["💬 Contact Admin", "👑 Get VIP"]]
    return {"keyboard": rows, "resize_keyboard": True, "one_time_keyboard": False}

def _pin_message(chat_id, message_id, disable_notification: bool = True):
    """Pins a message in a channel/group — requires the bot to be an admin
    there with 'pin messages' rights. Silent no-op on failure (e.g. bot isn't
    admin) rather than raising, since pinning is a nice-to-have, not critical."""
    if not message_id:
        return
    try:
        r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/pinChatMessage",
            json={"chat_id": chat_id, "message_id": message_id,
                  "disable_notification": disable_notification}, timeout=10)
        if not r.json().get("ok"):
            print(f"  [PIN] {chat_id} msg {message_id} failed: {r.json().get('description')}")
    except Exception as e:
        print(f"  [PIN] {chat_id} msg {message_id}: {e}")

def _send_plain_reply(chat_id, text: str, reply_to=None, reply_markup=None, protect: bool = False):
    """Direct sendMessage (no forward trick) — premium emoji fall back to plain
    glyphs, but this lets the message reply to an earlier one (reply_to = that
    message's message_id). Returns the new message_id, or None on failure.
    protect=True sets protect_content, blocking forward/save on that message —
    used for VIP-exclusive content so it can't be easily forwarded to non-payers."""
    text = _apply_premium_emojis(text)
    payload = {"chat_id": chat_id, "text": text, "parse_mode": "HTML", "disable_web_page_preview": True}
    if reply_to:
        payload["reply_parameters"] = {"message_id": reply_to, "allow_sending_without_reply": True}
    if reply_markup:
        payload["reply_markup"] = reply_markup
    if protect:
        payload["protect_content"] = True
    try:
        r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage", json=payload, timeout=10)
        rj = r.json()
        if rj.get("ok"):
            return rj["result"]["message_id"]
        print(f"  [PLAIN REPLY] {chat_id} rejected: {rj.get('description')}")
    except Exception as e:
        print(f"  [PLAIN REPLY] {chat_id}: {e}")
    return None

# ─── Userbot (real Telegram account) — see TG_USER_* comment ───────────────
# Telegram never delivers messages from one bot to ANOTHER bot via the Bot
# API — not a privacy-mode setting, a hard platform rule to prevent bot-loop
# spam (confirmed 2026-07-31: CLEXER's bot-token listener saw zero events for
# CoinTrendzBot's replies even with privacy mode off and the bot re-added to
# the group). So both sending the command AND watching for/downloading the
# reply have to happen through a genuine human-looking account — this runs a
# SECOND Telegram login (Telethon, a real user session, not the Bot API) in
# its own thread/event loop for exactly that. CLEXER's bot token is only used
# afterward, to actually POST the downloaded image bytes to real signal
# destinations — it never touches CoinTrendzBot directly.
_userbot_loop = None
_userbot_client = None
_userbot_ready = threading.Event()

# Every message seen in each shared group (both Kaito's own "/c <coin>" and
# CoinTrendzBot's replies), keyed by group_id str — periodically deleted to
# keep the group tidy instead of accumulating forever. See
# _clean_cointrendz_group / _any_scan_or_chart_busy and the cleanup loop
# started in main().
_cointrendz_group_msg_ids: dict = {}

# Rolling 24h "/c" request timestamps per group_id str — lets CLEXER switch to
# the next configured group BEFORE hitting CoinTrendzBot's own free-tier cap,
# instead of requests just silently failing once a group's limit is hit.
_cointrendz_group_requests: dict = {}
_cointrendz_active_group_idx = 0

# group_id str -> epoch until which CoinTrendzBot itself has confirmed this
# group is rate-limited ("Free group limit reached... try again in Xh Ym").
# Needed on top of the request-count guess above because that count only
# tracks requests made SINCE this bot process started — it has no idea a
# group is already mid-cooldown from before a restart/deploy, which is
# exactly what made the first version of this keep hammering an already-
# limited group instead of switching. See _on_group_message for where this
# gets set, from CoinTrendzBot's own rejection reply.
_cointrendz_group_blocked_until: dict = {}

def _cointrendz_mark_blocked(gid: str, reply_text: str = ""):
    """CoinTrendzBot rejected a request with its own rate-limit message —
    parses 'try again in Xh Ym' if present, otherwise assumes a conservative
    1-hour cooldown so the group isn't retried too soon."""
    minutes = 60
    m = re.search(r"(?:(\d+)\s*h)?\s*(?:(\d+)\s*m)?", reply_text or "", re.IGNORECASE)
    if m and (m.group(1) or m.group(2)):
        minutes = int(m.group(1) or 0) * 60 + int(m.group(2) or 0)
    _cointrendz_group_blocked_until[gid] = time.time() + minutes * 60
    print(f"  [COINTRENDZ] group {gid} confirmed rate-limited by CoinTrendzBot — blocked for {minutes}m")

def _cointrendz_group_count(gid: str) -> int:
    now = time.time()
    hits = [t for t in _cointrendz_group_requests.get(gid, []) if now - t < 86400]
    _cointrendz_group_requests[gid] = hits
    return len(hits)

def _cointrendz_pick_group(exclude: set = None) -> str:
    """Which group the NEXT '/c' request should go to — stays on the current
    one until it nears the 24h cap or CoinTrendzBot has actually confirmed
    it's rate-limited, then advances to the next configured group. `exclude`
    lets a caller rule out groups already tried in this same request (see
    _request_coin_chart_image's retry loop). If every group is unusable,
    falls back to whichever one is active rather than returning nothing — a
    rate-limited request just times out like any other missed chart."""
    global _cointrendz_active_group_idx
    exclude = exclude or set()
    now = time.time()
    for _ in range(len(COINTRENDZ_GROUP_IDS)):
        gid = COINTRENDZ_GROUP_IDS[_cointrendz_active_group_idx]
        _blocked = _cointrendz_group_blocked_until.get(gid, 0) > now
        if gid not in exclude and not _blocked and _cointrendz_group_count(gid) < COINTRENDZ_GROUP_LIMIT:
            return gid
        if _blocked:
            print(f"  [COINTRENDZ] group {gid} still in CoinTrendzBot's own cooldown — switching")
        elif gid not in exclude:
            print(f"  [COINTRENDZ] group {gid} near its 24h limit — switching to the next configured group")
        _cointrendz_active_group_idx = (_cointrendz_active_group_idx + 1) % len(COINTRENDZ_GROUP_IDS)
    return COINTRENDZ_GROUP_IDS[_cointrendz_active_group_idx]

def _any_scan_or_chart_busy() -> bool:
    """True while it's NOT safe to clean the shared group — i.e. a chart
    request is CURRENTLY mid-flight there (would be reading/deleting the very
    message it's waiting on). Originally also blocked on any Scan1/Scan2/
    TS1/TS2 cycle running anywhere in the bot, but the dense grid means some
    scan is running almost continuously — that check made cleanup basically
    never fire in practice (2026-07-31). A scan that hasn't reached its
    chart-request step yet doesn't actually conflict with cleaning this
    group, so this now only checks the real risk."""
    return _coin_chart_pending_event is not None

def _clean_cointrendz_group():
    """Deletes every tracked message in each shared CoinTrendzBot group via
    Kaito's account — only when nothing's using the group right now (see
    _any_scan_or_chart_busy). Silently no-ops if the userbot isn't
    connected, there's nothing to clean, or a scan is currently running —
    the next periodic check just tries again later."""
    if not any(_cointrendz_group_msg_ids.values()) or _any_scan_or_chart_busy():
        return
    if not (_userbot_ready.is_set() and _userbot_loop and _userbot_client):
        return
    import asyncio
    for _gid, _ids in list(_cointrendz_group_msg_ids.items()):
        if not _ids:
            continue
        _ids = list(_ids)
        _cointrendz_group_msg_ids[_gid] = []
        async def _do_delete(gid=_gid, ids=_ids):
            await _userbot_client.delete_messages(int(gid), ids)
            # delete_messages doesn't raise even when Telegram silently skips
            # messages Kaito's account lacks rights to delete in that specific
            # group (e.g. missing the "Delete Messages" admin permission) —
            # a call completing without an exception does NOT guarantee
            # anything was actually removed. Re-fetch the same ids: Telethon
            # returns None in a message's slot once it's genuinely gone.
            still_there = await _userbot_client.get_messages(int(gid), ids=ids)
            return [m.id for m in still_there if m is not None]
        fut = asyncio.run_coroutine_threadsafe(_do_delete(), _userbot_loop)
        try:
            survived = fut.result(timeout=20)
            if survived:
                print(f"[USERBOT] group {_gid}: {len(_ids)-len(survived)}/{len(_ids)} actually deleted — "
                      f"{len(survived)} still present (Kaito's account likely lacks the 'Delete Messages' "
                      f"admin permission in THIS group specifically)")
                _cointrendz_group_msg_ids.setdefault(_gid, []).extend(survived)
            else:
                print(f"[USERBOT] cleaned {len(_ids)} message(s) from CoinTrendzBot group {_gid}")
        except Exception as e:
            print(f"[USERBOT] group {_gid} cleanup failed (needs delete rights in that group?): {e}")
            # Put them back — nothing was actually deleted (or we can't tell), don't just lose track of them.
            _cointrendz_group_msg_ids.setdefault(_gid, []).extend(_ids)

# ─── CoinTrendzBot chart-image relay (2026-07-31) ──────────────────────────
# Requests are serialized (one at a time via _coin_chart_lock) because
# CoinTrendzBot's image reply carries no machine-readable caption identifying
# which coin it's answering — so "whatever it sends back next" is only a
# safe assumption if nothing else could be mid-flight at the same moment.
_coin_chart_lock = threading.Lock()
_coin_chart_pending_event = None
_coin_chart_pending_result: dict = {}

def _start_userbot():
    """Call once at startup (see main()). No-op if TG_USER_* isn't configured
    — chart-image requests just won't get a reply from CoinTrendzBot until
    it is (see userbot_login.py for how to generate TG_USER_SESSION_STRING)."""
    global _userbot_loop, _userbot_client
    if not (TG_USER_API_ID and TG_USER_API_HASH and TG_USER_SESSION_STRING):
        print("[USERBOT] Not configured (TG_USER_API_ID/API_HASH/SESSION_STRING) — "
              "CoinTrendzBot chart requests won't work until it is.")
        return
    def _run():
        global _userbot_loop, _userbot_client
        import asyncio
        from telethon import TelegramClient, events
        from telethon.sessions import StringSession
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        _userbot_loop = loop
        _userbot_client = TelegramClient(StringSession(TG_USER_SESSION_STRING),
            int(TG_USER_API_ID), TG_USER_API_HASH, loop=loop)
        try:
            # Telethon's client.start(), called outside an async function with
            # no currently-RUNNING loop, runs the whole login synchronously
            # itself (using the loop just set via set_event_loop internally)
            # and returns the client — NOT a coroutine. Wrapping it in
            # run_until_complete() fails with "An asyncio.Future, a coroutine
            # or an awaitable is required", since there's nothing left to
            # await by the time it returns. Just call it directly.
            _userbot_client.start()
            print("[USERBOT] Connected.")

            # Force a dialog-list sync so Telethon caches the access_hash for
            # every chat Kaito's account currently sits in — without this, a
            # group joined AFTER this session string was first generated can
            # fail to resolve as a valid Peer on send_message ("An invalid
            # Peer was used...") even though the account is genuinely a
            # member, purely because the client never looked it up yet.
            try:
                loop.run_until_complete(_userbot_client.get_dialogs())
                print("[USERBOT] Dialog list synced.")
            except Exception as e:
                print(f"[USERBOT] dialog sync failed (non-fatal): {e}")

            @_userbot_client.on(events.NewMessage(chats=[int(g) for g in COINTRENDZ_GROUP_IDS]))
            async def _on_group_message(event):
                # Runs on THIS thread's loop, for every new message in any of
                # the shared groups — Kaito's own account sees CoinTrendzBot's
                # replies fine, no bot-to-bot restriction applies here.
                # Track EVERY message here for the group-cleanup loop, before
                # the early-returns below — the cleanup should catch anything
                # that lands in any of these groups, not just chart replies.
                _cointrendz_group_msg_ids.setdefault(str(event.chat_id), []).append(event.id)
                if _coin_chart_pending_event is None:
                    return
                sender = await event.get_sender()
                _uname = (getattr(sender, "username", None) or "").lower()
                if _uname != COINTRENDZ_BOT_USERNAME:
                    return
                if not event.photo:
                    # No image — check if this is CoinTrendzBot's own rate-limit
                    # rejection ("Free group limit reached... try again in Xh
                    # Ym") so the group gets marked blocked and the caller can
                    # retry against another configured group immediately,
                    # instead of just waiting out the full timeout for nothing.
                    _rtext = (event.raw_text or "")
                    if "limit reached" in _rtext.lower() or "cooldown" in _rtext.lower():
                        _cointrendz_mark_blocked(str(event.chat_id), _rtext)
                        _coin_chart_pending_result["blocked_group"] = str(event.chat_id)
                        _coin_chart_pending_event.set()
                    return
                try:
                    _bytes = await event.download_media(file=bytes)
                except Exception as e:
                    print(f"[USERBOT] chart download failed: {e}")
                    return
                _coin_chart_pending_result["photo_bytes"] = _bytes
                _coin_chart_pending_event.set()

            _userbot_ready.set()
            loop.run_forever()
        except Exception as e:
            print(f"[USERBOT] connect error: {e}")
    threading.Thread(target=_run, daemon=True).start()

def _send_via_userbot(chat_id, text: str, timeout: float = 10.0):
    """Sends `text` into `chat_id` as the real user account. Synchronous
    wrapper around the async Telethon client running in its own loop/thread —
    callers don't need to know or care that it's asyncio underneath.
    Returns the sent message's id (truthy) on success, None on failure.
    Callers that only care about success/failure can still just do
    `if _send_via_userbot(...):` — non-zero/non-None ids are always truthy."""
    if not _userbot_ready.wait(5):
        return None
    if not (_userbot_loop and _userbot_client):
        return None
    import asyncio
    fut = asyncio.run_coroutine_threadsafe(_userbot_client.send_message(int(chat_id), text), _userbot_loop)
    try:
        _msg = fut.result(timeout=timeout)
        return _msg.id
    except Exception as e:
        print(f"[USERBOT] send failed: {e}")
        return None

def _request_coin_chart_image(coin: str, timeout: float = 30.0):
    """Sends '/c <coin>' to whichever configured CoinTrendzBot group is
    currently active (see _cointrendz_pick_group — auto-switches groups
    before hitting CoinTrendzBot's free-tier ~250-command/24h cap), then
    waits (up to `timeout`s) for the userbot's own NewMessage handler
    (_on_group_message, registered in _start_userbot) to download
    CoinTrendzBot's image reply there. Returns the raw image bytes — a
    file_id obtained via Kaito's user session isn't valid in CLEXER's bot-
    token API calls, so callers must upload these bytes directly (multipart),
    not reference a file_id. Returns None on timeout/failure; callers must
    treat that as "no chart available this time," never block a real trade
    signal on it."""
    global _coin_chart_pending_event
    if not COINTRENDZ_GROUP_IDS:
        return None
    with _coin_chart_lock:
        _tried = set()
        for _attempt in range(len(COINTRENDZ_GROUP_IDS)):
            _gid = _cointrendz_pick_group(exclude=_tried)
            _tried.add(_gid)
            _ev = threading.Event()
            _coin_chart_pending_event = _ev
            _coin_chart_pending_result.clear()
            _sent_id = _send_via_userbot(_gid, f"/c {coin.lower()}")
            if not _sent_id:
                print(f"  [COINTRENDZ] userbot send failed for /c {coin} (group {_gid}) — "
                      f"likely not reachable by the userbot account (unresolved peer/not a member)")
                _coin_chart_pending_event = None
                # Don't just give up — a group that's flat-out unreachable
                # (wrong id, userbot never joined, etc.) shouldn't take the
                # whole relay down when another configured group is fine.
                # Skip it for an hour so every request doesn't re-attempt a
                # doomed send, and try the next group in this same call.
                _cointrendz_group_blocked_until[_gid] = time.time() + 3600
                continue
            # Track our own "/c coin" command message directly — Telethon's
            # NewMessage event doesn't reliably fire for messages the SAME
            # client just sent (Telegram doesn't always push an update back
            # for your own outgoing message), so relying only on
            # _on_group_message left these commands never getting cleaned up
            # even though CoinTrendzBot's image replies (genuinely incoming)
            # were deleted fine.
            _cointrendz_group_msg_ids.setdefault(_gid, []).append(_sent_id)
            _cointrendz_group_requests.setdefault(_gid, []).append(time.time())
            _got = _ev.wait(timeout)
            _coin_chart_pending_event = None
            if not _got:
                return None
            if _coin_chart_pending_result.get("blocked_group") == _gid:
                # CoinTrendzBot just confirmed this group is rate-limited —
                # already marked blocked (see _on_group_message); try the
                # next configured group right away instead of giving up.
                continue
            return _coin_chart_pending_result.get("photo_bytes")
        return None

def _send_chart_image_for_reply_map(reply_map: dict, photo_bytes: bytes):
    """Uploads an already-downloaded chart image (raw bytes, from the
    userbot) to every destination a signal's entry text just went to, as a
    genuine reply-threaded follow-up to that entry message — reply_map is
    exactly what send_entry_signal returned, so this reuses both its keys
    (which chat) and values (which message_id to thread under) instead of
    re-deriving the tier-routing logic. Multipart upload, not a file_id —
    see _request_coin_chart_image's docstring for why."""
    if not photo_bytes:
        return
    for key, mid in (reply_map or {}).items():
        if key == "ch1": cid = TELEGRAM_CHANNEL_ID
        elif ":" in key: cid = key.split(":", 1)[1]
        else: continue
        if not cid: continue
        try:
            _data = {"chat_id": cid}
            if mid:
                _data["reply_parameters"] = json.dumps({"message_id": mid, "allow_sending_without_reply": True})
            requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendPhoto",
                data=_data, files={"photo": ("chart.png", photo_bytes)}, timeout=20)
        except Exception as e:
            print(f"  [CHART IMG] send to {cid} failed: {e}")

def _attach_chart_image_async(coin: str, reply_map: dict):
    """Fires off the chart fetch+attach in its own background thread — the
    real trade signal (already sent by the time this is called) must never
    wait on a third-party bot's reply."""
    def _run():
        _img = _request_coin_chart_image(coin)
        if _img:
            _send_chart_image_for_reply_map(reply_map, _img)
    threading.Thread(target=_run, daemon=True).start()

def send_entry_signal(text: str, include_ch2: bool = True, tier_routed: bool = False, share_free: bool = True,
                       locked_text: str = None, sig_id: str = None, react_category: str = None) -> dict:
    """Sends a trade's entry signal via plain sendMessage (confirmed via /testreply
    to render premium emoji correctly — the old forward-relay trick actually LOSES
    them despite the original assumption it preserved them), and captures each
    destination's message_id. Store the returned dict on the trade (t["reply_map"] = ...)
    so later send_lifecycle_reply() calls can thread TP1/TP2/SL/Trailing-SL/timeout
    messages as genuine replies to this entry post in every channel it went to.

    locked_text + sig_id: when both given AND share_free is False (i.e. this
    signal is genuinely VIP-exclusive — previously Free got NOTHING for these
    at entry, only a generic "VIP hit TP1" teaser later via _notify_free_late),
    the FREE channel now gets this redacted variant instead, plus an Unlock
    button deep-linking to the bot's DM (/start unlock_<sig_id>). When
    share_free is True, the signal was always meant to be free — Free keeps
    getting the real, unredacted `text`, completely unchanged. VIP and the
    legacy channels always get the real `text` either way."""
    ids = {}
    channels = [("1", TELEGRAM_CHANNEL_ID)]  # channel 2 retired 2026-07-31 — now just another VIP channel via CHANNELS/tier routing below, no longer a hardcoded second broadcast target
    for key, cid in channels:
        if not cid: continue
        if channel_paused.get(key): continue
        if key == "2" and not include_ch2: continue
        mid = _send_plain_reply(cid, text)
        if mid: ids[f"ch{key}"] = mid
    if tier_routed:
        for cid in _channels_by_tier("vip"):
            mid = _send_plain_reply(cid, text, protect=True)  # VIP-exclusive — block forward/save
            if mid: ids[f"vip:{cid}"] = mid
        if share_free:
            for cid in _channels_by_tier("free"):
                mid = _send_plain_reply(cid, text)
                if mid: ids[f"free:{cid}"] = mid
        elif locked_text and sig_id:
            _free_markup = None
            _uname = _get_bot_username()
            if _uname:
                _free_markup = {"inline_keyboard": [[
                    # Telegram deep-link start params only allow [A-Za-z0-9_-] — sig_id
                    # is "#CLEXxxxxxx", so the "#" must be stripped here (it would
                    # otherwise be parsed as a URL fragment and never reach the bot at
                    # all) and re-added when /start parses it back (see handle_command).
                    {"text": "🔓 Unlock Signal", "url": f"https://t.me/{_uname}?start=unlock_{sig_id.lstrip('#')}", "style": "primary"}]]}
            for cid in _channels_by_tier("free"):
                mid = _send_plain_reply(cid, locked_text, reply_markup=_free_markup)
                if mid: ids[f"free:{cid}"] = mid
    if react_category:
        _react_to_ids(ids, react_category)
    return ids

def _tp_buttons():
    """Open Bot + Get VIP buttons — attached to every TP1/TP2 message, per
    admin request, so users can act right from the win notification. Get VIP
    deep-links straight into the /vip offer screen (same t.me/bot?start=vip
    pattern used elsewhere) rather than just opening a blank DM."""
    row = []
    _uname = _get_bot_username()
    if _uname:
        row.append({"text": "🤖 Open Bot", "url": f"https://t.me/{_uname}", "style": "primary"})
        row.append({"text": "👑 Get VIP", "url": f"https://t.me/{_uname}?start=vip", "style": "primary"})
    return {"inline_keyboard": [row]} if row else None

def send_lifecycle_reply(text: str, reply_map: dict, include_ch2: bool = True, tier_routed: bool = False, share_free: bool = True, reply_markup=None,
                          locked_text: str = None, exclude_ch2: bool = False, react_category: str = None):
    """Sends a TP1/TP2/SL/Trailing-SL/timeout follow-up as a genuine Telegram reply
    to that trade's entry-signal message in every destination it has a stored
    message_id for (reply_map, from send_entry_signal). Uses plain sendMessage —
    forwardMessage can't set reply-to — so premium emoji fall back to plain glyphs
    on these specific messages. A destination missing from reply_map (e.g. entry
    capture failed, or reply_map is empty/old-format) just gets a normal post.

    locked_text: when given AND share_free is False (signal was locked at
    entry), Free gets this redacted variant instead of nothing — same idea as
    send_entry_signal's locked_text, for follow-ups like Trailing SL where a
    generic "no real numbers" version still makes sense to show.

    exclude_ch2: skips TELEGRAM_CHANNEL_ID_2 (VIP Mirror) specifically —
    used for SL/BE follow-ups, which VIP Mirror subscribers don't want in
    their feed (admin request, same reasoning as no-signal notices)."""
    reply_map = reply_map or {}
    ids = {}
    channels = [("1", TELEGRAM_CHANNEL_ID)]  # channel 2 retired — see send_entry_signal's matching comment
    for key, cid in channels:
        if not cid: continue
        if channel_paused.get(key): continue
        if key == "2" and not include_ch2: continue
        mid = _send_plain_reply(cid, text, reply_to=reply_map.get(f"ch{key}"), reply_markup=reply_markup)
        if mid: ids[f"ch{key}"] = mid
    if tier_routed:
        for cid in _channels_by_tier("vip"):
            if exclude_ch2 and str(cid) == str(TELEGRAM_CHANNEL_ID_2):
                continue
            # No Open Bot / Get VIP buttons in VIP itself — these members are
            # already VIP and already using the bot, so both buttons are
            # dead weight here. Free/legacy channels below keep them since
            # that's where the upsell/bot-discovery actually matters.
            mid = _send_plain_reply(cid, text, reply_to=reply_map.get(f"vip:{cid}"), reply_markup=None, protect=True)
            if mid: ids[f"vip:{cid}"] = mid
        if share_free:
            for cid in _channels_by_tier("free"):
                mid = _send_plain_reply(cid, text, reply_to=reply_map.get(f"free:{cid}"), reply_markup=reply_markup)
                if mid: ids[f"free:{cid}"] = mid
        elif locked_text:
            for cid in _channels_by_tier("free"):
                mid = _send_plain_reply(cid, locked_text, reply_to=reply_map.get(f"free:{cid}"), reply_markup=reply_markup)
                if mid: ids[f"free:{cid}"] = mid
    if react_category:
        _react_to_ids(ids, react_category)
    return ids

def _send_sl_and_log(text: str, reply_map: dict, sig_id: str, result: str, **kwargs) -> dict:
    """Same as send_lifecycle_reply, but also records this signal's Free-channel
    SL-hit message_id + final result (SL/BE) so /clearslfree can later find and
    delete exactly this signal's messages — only if result is a real SL, never
    for BE. See _track_free_sl/_finalize_free_sl for the actual bookkeeping.
    Excludes Channel 2 (VIP Mirror) for a real SL only — admin request, BE
    (breakeven, i.e. TP1 already hit) still posts there as normal.

    Auto-reacts with the "sl" category on a real loss, "be" on a no-loss
    exit — caller can still override via react_category= in kwargs."""
    kwargs.setdefault("exclude_ch2", result == "SL")
    kwargs.setdefault("react_category", "sl" if result == "SL" else "be")
    ids = send_lifecycle_reply(text, reply_map, **kwargs)
    for k, v in (ids or {}).items():
        if k.startswith("free:"):
            _track_free_sl(sig_id, k.split(":", 1)[1], "sl_mid", v)
    _finalize_free_sl(sig_id, result)
    return ids

def send_to_tier_channels(text: str, share_free: bool, exclude_ch2: bool = False):
    """Sends to every registered VIP channel always, and to FREE channels only
    if share_free is True (the daily quota decision made once per signal).
    Uses the true-forwardMessage relay so custom_emoji survives; falls back
    to a direct send only if the forward relay itself fails.

    exclude_ch2: skips TELEGRAM_CHANNEL_ID_2 (VIP Mirror) specifically —
    used for "no signal found" notices, which VIP Mirror subscribers don't
    want cluttering their feed (admin request)."""
    text = _apply_premium_emojis(text)
    for cid in _channels_by_tier("vip"):
        if exclude_ch2 and str(cid) == str(TELEGRAM_CHANNEL_ID_2):
            continue
        if _send_via_true_forward(text, cid, "vip", protect=True):
            continue
        try:
            r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage",
                json={"chat_id": cid, "text": text, "parse_mode": "HTML", "disable_web_page_preview": True,
                      "protect_content": True}, timeout=10)
            rj = r.json()
            if not rj.get("ok"):
                print(f"  [TIER CHANNEL] vip {cid} rejected: {rj.get('description')}")
        except Exception as e: print(f"  [TIER CHANNEL] vip {cid}: {e}")
    if share_free:
        for cid in _channels_by_tier("free"):
            if _send_via_true_forward(text, cid, "free"):
                continue
            try:
                r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage",
                    json={"chat_id": cid, "text": text, "parse_mode": "HTML", "disable_web_page_preview": True}, timeout=10)
                rj = r.json()
                if not rj.get("ok"):
                    print(f"  [TIER CHANNEL] free {cid} rejected: {rj.get('description')}")
                else:
                    _ents = rj.get("result", {}).get("entities", [])
                    _ce = [e for e in _ents if e.get("type") == "custom_emoji"]
                    print(f"  [TIER CHANNEL DEBUG] free {cid}: {len(_ce)} custom_emoji entities echoed back of {len(_ents)} total entities")
            except Exception as e: print(f"  [TIER CHANNEL] free {cid}: {e}")

def _all_channel_ids() -> list:
    """Every destination CLEXER posts signals to — the legacy Signal channel
    (skipping it if currently paused via /pausechannel) + all VIP/Free tier
    channels. Channel 2 retired as a hardcoded destination (2026-07-31) —
    it's now just another entry in the VIP tier list, so it's already
    covered by the _channels_by_tier("vip") loop below; listing it again
    here would double it up in anything that iterates this (e.g. broadcast)."""
    ids = []
    if TELEGRAM_CHANNEL_ID and not channel_paused.get("1"): ids.append(("legacy1", TELEGRAM_CHANNEL_ID))
    for cid in _channels_by_tier("vip"): ids.append(("vip", cid))
    for cid in _channels_by_tier("free"): ids.append(("free", cid))
    return ids

# ─── Daily TP1/TP2/SL tracker — drives the streak promo, SL reassurance, and
# end-of-day recap. Trades are bucketed by the IST calendar day they were
# OPENED on (their entry_date), not by whichever day their TP1/TP2/SL happens
# to fire on — so a trade opened on the 14th that closes at 12:02 AM on the
# 15th still counts toward the 14th's recap, exactly like every other trade
# from that day. Once a day's recap has been sent, any later-arriving result
# for a trade from that day is simply not recapped again (there's no way to
# retroactively edit an already-sent Telegram message). ────────────────────
_daily_buckets: dict = {}   # entry_date str -> {"date","tp1","tp2","sl","free_tp1","tp1_promo_sent","trades"}
_daily_summary_last_sent_date = ""
_weekly_summary_last_sent = ""   # ISO date string of the Monday whose week was last recapped
_monthly_summary_last_sent = ""  # "YYYY-MM" of the month last recapped

def _save_daily_buckets():
    """Persists _daily_buckets both to local disk AND the central store — local
    disk alone was the original bug: on Railway, the app filesystem is NOT
    guaranteed to survive a redeploy unless DATA_DIR is on a mounted volume, so
    a disk-only save can silently reset to empty on every push exactly like the
    in-memory version did. Pushing to the central store (same one save_state()
    and the slot-stats system use) makes this survive redeploys regardless of
    whether local disk does. Cheap to call on every _track_daily_result()
    update since the payload is tiny."""
    _blob = {"buckets": _daily_buckets, "last_sent": _daily_summary_last_sent_date,
              "weekly_last_sent": _weekly_summary_last_sent, "monthly_last_sent": _monthly_summary_last_sent}
    try:
        with open(os.path.join(DATA_DIR, "daily_buckets.json"), "w") as f:
            json.dump(_blob, f)
    except Exception as e:
        print(f"[DAILY BUCKETS] local save error: {e}")
    # Active-server gate — see save_settings()'s comment.
    if CLEXER_API_URL and is_active_server():
        try:
            _kv_push("daily_buckets", _blob)
        except Exception as e:
            print(f"[DAILY BUCKETS] central push error: {e}")

def _load_daily_buckets():
    global _daily_buckets, _daily_summary_last_sent_date, _weekly_summary_last_sent, _monthly_summary_last_sent
    try:
        d = None
        path = os.path.join(DATA_DIR, "daily_buckets.json")
        if CLEXER_API_URL:
            r = _central_get("/kv/daily_buckets")
            if r is not None and r.ok:
                d = _kv_pick_newer(path, r.json(), "DAILY BUCKETS")
        if d is None and os.path.exists(path):
            with open(path) as f:
                d = json.load(f)
        if d is not None:
            _daily_buckets = d.get("buckets", {})
            _daily_summary_last_sent_date = d.get("last_sent", "")
            _weekly_summary_last_sent = d.get("weekly_last_sent", "")
            _monthly_summary_last_sent = d.get("monthly_last_sent", "")
            print(f"[DAILY BUCKETS] Restored {len(_daily_buckets)} day(s)")
    except Exception as e:
        print(f"[DAILY BUCKETS] load error: {e}")

def _ist_date_str(epoch_seconds=None) -> str:
    """IST calendar-day string for a given epoch timestamp, or today if none given."""
    if epoch_seconds is None:
        return now_ist().strftime("%Y-%m-%d")
    try:
        return (datetime.fromtimestamp(float(epoch_seconds), timezone.utc) + IST).strftime("%Y-%m-%d")
    except Exception:
        return now_ist().strftime("%Y-%m-%d")

def _get_daily_bucket(date_str: str) -> dict:
    if date_str not in _daily_buckets:
        _daily_buckets[date_str] = {"date": date_str, "tp1": 0, "tp2": 0, "sl": 0,
                                     "free_tp1": 0, "tp1_promo_sent": False, "trades": []}
        # Bound memory — keep last 35 days. Was 7 (daily recap only needs
        # yesterday), bumped to cover a full calendar month + a few days'
        # buffer so the weekly/monthly recaps (added 2026-08-04) can still
        # find every day's bucket when their own boundary check fires.
        for _old_date in sorted(_daily_buckets.keys())[:-35]:
            del _daily_buckets[_old_date]
    return _daily_buckets[date_str]

