def _build_recap_text(trades: list, date_str: str, include_sl: bool = True) -> str:
    tp2_list  = [t for t in trades if t["result"] == "TP2"]
    tp1_list  = [t for t in trades if t["result"] == "TP1"]
    sl_list   = [t for t in trades if t["result"] == "SL"] if include_sl else []
    to_list   = [t for t in trades if t["result"] == "TIMEOUT"]
    lines = [f"📊 <b>Daily Recap — {date_str}</b>\n"]
    if tp2_list:
        lines.append("🏆 <b>TP2 Hit:</b>")
        lines += [f"✅ {t['symbol']} — {t['time']}" for t in tp2_list]
        lines.append("")
    if tp1_list:
        lines.append("💰 <b>TP1 Hit:</b>")
        lines += [f"🎯 {t['symbol']} — {t['time']}" for t in tp1_list]
        lines.append("")
    if sl_list:
        lines.append("🛑 <b>SL Hit:</b>")
        lines += [f"❌ {t['symbol']} — {t['time']}" for t in sl_list]
        lines.append("")
    if to_list:
        lines.append("⏰ <b>Timeout:</b>")
        lines += [f"➖ {t['symbol']} — {t['time']}" +
                  (f" ({t['pnl']:+.2f}%)" if t.get("pnl") is not None else "")
                  for t in to_list]
    return "\n".join(lines)

def _send_daily_summary(tracker: dict):
    """End-of-day recap for one specific day's tracker snapshot — every TP1/TP2/SL
    that actually triggered on that calendar day and was tier-routed, with premium
    emoji via forward. VIP gets every tier-routed trade (VIP-only + VIP+Free);
    Free only gets the subset that was also shown in Free — so the two recaps
    are no longer identical, and Signal-only trades never appear in either.
    Only counts trades whose TP1/TP2/SL actually fired on this tracker's own
    date — a trade opened the day before but not yet closed is simply absent
    from the trades list (never added until it actually triggers), and a trade
    that triggers just after midnight belongs to the NEXT day's tracker/recap,
    never this one."""
    date_str = tracker.get("date", "")
    all_trades = [t for t in tracker.get("trades", []) if t.get("tier_routed")]
    if not all_trades:
        return
    vip_text = _apply_premium_emojis(_build_recap_text(all_trades, date_str))
    # Channel 2 (VIP Mirror) gets its own SL-free variant — same reasoning as
    # the live SL/no-signal exclusions above, admin request.
    ch2_text = _apply_premium_emojis(_build_recap_text(all_trades, date_str, include_sl=False))
    for cid in _channels_by_tier("vip"):
        _text = ch2_text if str(cid) == str(TELEGRAM_CHANNEL_ID_2) else vip_text
        _mid = _send_via_true_forward(_text, cid, "daily-summary-vip", protect=True)
        if not _mid:
            try:
                r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage",
                    json={"chat_id": cid, "text": _text, "parse_mode": "HTML", "protect_content": True}, timeout=10)
                _mid = r.json().get("result", {}).get("message_id")
            except Exception as e: print(f"  [DAILY SUMMARY] vip {cid}: {e}")
        if isinstance(_mid, int):
            _pin_message(cid, _mid)
    free_trades = [t for t in all_trades if t.get("free_shown")]
    if free_trades:
        free_text = _apply_premium_emojis(_build_recap_text(free_trades, date_str))
        for cid in _channels_by_tier("free"):
            _mid = _send_via_true_forward(free_text, cid, "daily-summary-free")
            if not _mid:
                try:
                    r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage",
                        json={"chat_id": cid, "text": free_text, "parse_mode": "HTML"}, timeout=10)
                    _mid = r.json().get("result", {}).get("message_id")
                except Exception as e: print(f"  [DAILY SUMMARY] free {cid}: {e}")
            if isinstance(_mid, int):
                _pin_message(cid, _mid)

def _gather_period_trades(date_strs: list) -> list:
    """Concatenates the tier_routed trades from every date in date_strs that
    still has a bucket (older days may have already been pruned — see
    _get_daily_bucket's 35-day retention). Used by the weekly/monthly recaps
    to pull a whole period's worth of trades out of the same per-day buckets
    the daily recap already tracks, instead of a separate data store."""
    trades = []
    for d in date_strs:
        b = _daily_buckets.get(d)
        if b:
            trades += [t for t in b.get("trades", []) if t.get("tier_routed")]
    return trades

def _build_period_recap_text(trades: list, title: str, include_sl: bool = True) -> str:
    """Weekly/monthly recap text — summarized (counts + win rate) rather than
    the daily recap's itemized per-trade list, since a week or month of
    trades listed individually would make an unreadably long Telegram
    message. Same TP2/TP1/SL/TIMEOUT split as _build_recap_text."""
    tp2 = [t for t in trades if t["result"] == "TP2"]
    tp1 = [t for t in trades if t["result"] == "TP1"]
    sl  = [t for t in trades if t["result"] == "SL"] if include_sl else []
    to  = [t for t in trades if t["result"] == "TIMEOUT"]
    wins = len(tp1) + len(tp2)
    decided = wins + len(sl)
    lines = [f"📊 <b>{title}</b>\n"]
    lines.append(f"🏆 TP2 Hit: <b>{len(tp2)}</b>")
    lines.append(f"💰 TP1 Hit: <b>{len(tp1)}</b>")
    if include_sl:
        lines.append(f"🛑 SL Hit: <b>{len(sl)}</b>")
    if to:
        lines.append(f"⏰ Timeout: <b>{len(to)}</b>")
    lines.append("")
    lines.append(f"✅ Win Rate: <b>{wins / decided * 100:.0f}%</b> ({wins}/{decided})" if decided else "✅ Win Rate: —")
    return "\n".join(lines)

def _send_period_summary(trades: list, title: str, tag: str):
    """Sends a weekly/monthly recap — same channel routing + pin behavior as
    _send_daily_summary (VIP gets every tier-routed trade with SL, Channel 2/
    VIP Mirror gets the SL-free variant, Free gets only the free_shown
    subset), just built from _build_period_recap_text's summary instead of
    an itemized list. No-ops if there's nothing tier_routed for the period."""
    if not trades:
        return
    vip_text = _apply_premium_emojis(_build_period_recap_text(trades, title))
    ch2_text = _apply_premium_emojis(_build_period_recap_text(trades, title, include_sl=False))
    for cid in _channels_by_tier("vip"):
        _text = ch2_text if str(cid) == str(TELEGRAM_CHANNEL_ID_2) else vip_text
        _mid = _send_via_true_forward(_text, cid, f"{tag}-vip", protect=True)
        if not _mid:
            try:
                r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage",
                    json={"chat_id": cid, "text": _text, "parse_mode": "HTML", "protect_content": True}, timeout=10)
                _mid = r.json().get("result", {}).get("message_id")
            except Exception as e: print(f"  [{tag.upper()} SUMMARY] vip {cid}: {e}")
        if isinstance(_mid, int):
            _pin_message(cid, _mid)
    free_trades = [t for t in trades if t.get("free_shown")]
    if free_trades:
        free_text = _apply_premium_emojis(_build_period_recap_text(free_trades, title))
        for cid in _channels_by_tier("free"):
            _mid = _send_via_true_forward(free_text, cid, f"{tag}-free")
            if not _mid:
                try:
                    r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage",
                        json={"chat_id": cid, "text": free_text, "parse_mode": "HTML"}, timeout=10)
                    _mid = r.json().get("result", {}).get("message_id")
                except Exception as e: print(f"  [{tag.upper()} SUMMARY] free {cid}: {e}")
            if isinstance(_mid, int):
                _pin_message(cid, _mid)

def _track_daily_result(symbol: str, result: str, tier_routed: bool = False, free_shown: bool = False,
                         tp1_detail: dict = None, entry_date: str = None, sig_id: str = None, pnl: float = None):
    """Call this at every genuine TP1/TP2/SL close (result: 'TP1'/'TP2'/'SL').
    Drives the 3rd-Free-TP1-of-the-day promo and feeds the end-of-day recap.
    entry_date: the IST calendar day this TRADE was opened on (not today) —
    the result is credited to that day's bucket, so a trade opened on the
    14th that closes just after midnight on the 15th still recaps under the
    14th. Defaults to today if not given (e.g. BTC call sites not yet passing it).
    tier_routed: True if this trade was shown in VIP (and maybe Free) — only
    tier_routed trades are eligible for the recap at all (Signal-only never appears).
    free_shown: True if also visible in the Free channel — builds Free's own
    (shorter) recap and gates the 3rd-TP1 streak promo.
    tp1_detail: {'tag','side','tp1','sl_be','tp2'} for the promo's message.
    sig_id: same trade's signal id — when the trade later runs to TP2, its
    earlier TP1 recap line (same sig_id) is dropped so the recap only ever
    shows the trade's final/best result, not both TP1 and TP2 for one trade."""
    date_str = entry_date or _ist_date_str()
    bucket = _get_daily_bucket(date_str)
    key = result.lower()
    bucket[key] = bucket.get(key, 0) + 1
    if tier_routed:
        if result == "TP2" and sig_id:
            bucket["trades"] = [tr for tr in bucket["trades"]
                                 if not (tr.get("sig_id") == sig_id and tr.get("result") == "TP1")]
        bucket["trades"].append({
            "symbol": symbol, "result": result,
            "time": now_ist().strftime("%I:%M %p IST"),
            "free_shown": free_shown, "tier_routed": True, "sig_id": sig_id,
            "pnl": pnl,
        })
    if result == "TP1" and free_shown:
        bucket["free_tp1"] = bucket.get("free_tp1", 0) + 1
        if bucket["free_tp1"] == 3 and not bucket["tp1_promo_sent"]:
            bucket["tp1_promo_sent"] = True
            _send_tp1_streak_promo(symbol, tp1_detail or {})
    # TP2 congrats broadcast disabled — admin asked to stop sending it.
    _save_daily_buckets()

def _daily_summary_loop():
    """Background thread — fires the recap for the day that just ENDED, shortly
    after midnight IST, reading that day's bucket from _daily_buckets (trades
    are grouped by the day they were OPENED, so this only ever grabs trades
    that actually belong to the outgoing day). Checked every 60s for up to 10
    minutes after midnight, to give any TP1/TP2/SL that fires right at the
    rollover boundary time to land in its bucket before the recap is sent.
    Whatever hasn't landed by then is simply not included — a trade opened on
    day D that resolves after D's recap has already gone out is not recapped
    again on any later day.

    Also fires the WEEKLY recap (Monday, for the Mon-Sun week that just
    ended) and MONTHLY recap (the 1st, for the calendar month that just
    ended) — same midnight-window check, same _daily_buckets data, just
    summarized instead of itemized (see _build_period_recap_text). Relies
    on _get_daily_bucket's 35-day retention to still have every day's
    bucket by the time these fire (2026-08-04 admin request)."""
    global _daily_summary_last_sent_date, _weekly_summary_last_sent, _monthly_summary_last_sent
    while True:
        try:
            now = datetime.now(timezone.utc) + IST
            if now.hour == 0 and now.minute < 10:
                yesterday_str = (now - timedelta(days=1)).strftime("%Y-%m-%d")
                if _daily_summary_last_sent_date != yesterday_str:
                    bucket = _daily_buckets.get(yesterday_str)
                    if bucket and bucket.get("trades"):
                        _send_daily_summary(bucket)
                        _daily_summary_last_sent_date = yesterday_str  # only lock once actually sent
                        _save_daily_buckets()
                if now.weekday() == 0:  # Monday
                    _week_end = now.date() - timedelta(days=1)      # yesterday = Sunday
                    _week_start = _week_end - timedelta(days=6)     # the Monday before
                    _week_start_str = _week_start.strftime("%Y-%m-%d")
                    if _weekly_summary_last_sent != _week_start_str:
                        _week_dates = [(_week_start + timedelta(days=i)).strftime("%Y-%m-%d") for i in range(7)]
                        _trades = _gather_period_trades(_week_dates)
                        if _trades:
                            _title = f"Weekly Recap — {_week_start.strftime('%b %d')} to {_week_end.strftime('%b %d')}"
                            _send_period_summary(_trades, _title, "weekly-summary")
                            _weekly_summary_last_sent = _week_start_str  # only lock once actually sent
                            _save_daily_buckets()
                if now.day == 1:
                    _month_end = now.date() - timedelta(days=1)     # yesterday = last day of the month that just ended
                    _month_key = _month_end.strftime("%Y-%m")
                    if _monthly_summary_last_sent != _month_key:
                        _month_start = _month_end.replace(day=1)
                        _n_days = (_month_end - _month_start).days + 1
                        _month_dates = [(_month_start + timedelta(days=i)).strftime("%Y-%m-%d") for i in range(_n_days)]
                        _trades = _gather_period_trades(_month_dates)
                        if _trades:
                            _title = f"Monthly Recap — {_month_end.strftime('%B %Y')}"
                            _send_period_summary(_trades, _title, "monthly-summary")
                            _monthly_summary_last_sent = _month_key  # only lock once actually sent
                            _save_daily_buckets()
        except Exception as e:
            print(f"  [DAILY SUMMARY LOOP] {e}")
        time.sleep(60)

ACTIVE_PROFILE = "mine"   # "mine" or "coadmin" — which scan-settings snapshot is currently live
_SETTINGS_PROFILES = {"mine": {}, "coadmin": {}}  # each holds a snapshot of every setting co-admin can touch

