def _chat_call_gemini_text(history: list, extra_system: str = "") -> str:
    # Google Search grounding was tried here (2026-08-06) and reverted the same
    # day — this account's free-tier Gemini quota is only 5 RPM / 20 RPD (see
    # _CHAT_TEXT_MODEL comment), and confirmed via a real 429 in production,
    # a "try grounded, fall back on failure" pattern DOUBLES API calls per
    # reply whenever grounding doesn't go through, burning the already-scarce
    # daily quota twice as fast. Not worth it on this account — back to one
    # plain call, no source links, same as before grounding was ever added.
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{_CHAT_TEXT_MODEL}:generateContent?key={GEMINI_API_KEY}"
    _sys = _CHAT_SYSTEM_PROMPT + (f"\n\n{extra_system}" if extra_system else "")
    body = {
        "contents": history,
        "systemInstruction": {"parts": [{"text": _sys}]},
    }
    r = requests.post(url, headers=_gemini_headers(), json=body, timeout=30)
    if not r.ok:
        raise Exception(f"{r.status_code} {r.reason} — {r.text[:500]}")
    d = r.json()
    parts = d.get("candidates", [{}])[0].get("content", {}).get("parts", [])
    return "".join(p.get("text","") for p in parts).strip() or "…"

def _is_claude_model(model_id: str) -> bool:
    return model_id.startswith("claude-")

def _chat_call_claude_text(history: list, model_id: str, extra_system: str = "", gateway_override: str = None) -> str:
    """Same conversation history format as Gemini (role 'user'/'model', one
    text part each) — translated to Claude's 'user'/'assistant' shape so
    /model can swap engines without touching how history is stored.

    Non-Claude catalog models (GPT/GLM/Kimi) always use Aerolink regardless of
    any gateway setting — Anthropic's own Direct API has no knowledge of those
    model names and would just error out — and skip the Claude-only
    thinking/output_config params, which other providers proxied through
    Aerolink aren't confirmed to understand.

    gateway_override: "direct" or "aerolink" from the current session's
    in-chat "switch direct"/"switch free" command (see
    _CHAT_GATEWAY_SWITCH_CMDS); None falls back to the CHAT_USE_AEROLINK
    global default. Only matters for genuine claude-* models — see above."""
    messages = [{"role": "assistant" if h["role"] == "model" else "user",
                 "content": h["parts"][0]["text"]} for h in history]
    _is_claude = _is_claude_model(model_id)
    if not _is_claude:
        _want_aero = True
    elif gateway_override is not None:
        _want_aero = gateway_override == "aerolink"
    else:
        _want_aero = CHAT_USE_AEROLINK
    client = _claude_client("chat", use_aerolink=_want_aero)
    # Split system into a cached static block (_CHAT_SYSTEM_PROMPT, byte-identical
    # on every single chat call) + an uncached dynamic block (extra_system, varies
    # per admin-topic/session) — admin request 2026-08-06. Prompt caching is a
    # prefix match, so the static part must come first and stay untouched;
    # cache_control on it lets every subsequent Boki/Pechi call in the same
    # ~5min window read it at ~0.1x cost instead of paying full price every time.
    _system_blocks = [{"type": "text", "text": _CHAT_SYSTEM_PROMPT, "cache_control": {"type": "ephemeral"}}]
    if extra_system:
        _system_blocks.append({"type": "text", "text": extra_system})
    _kwargs = dict(model=model_id, max_tokens=2000,
                   system=_system_blocks,
                   messages=messages)
    if _is_claude:
        _kwargs["thinking"] = {"type": "adaptive"}
        _kwargs["output_config"] = {"effort": "medium"}
    resp = client.messages.create(**_kwargs)
    return _claude_text(resp) or "…"

_LUMOSEL_OPENAI_URL = "https://api.lumosel.vip/v1/chat/completions"

def _chat_call_openai_shape(history: list, model_id: str, extra_system: str = "", attempt: int = 0) -> str:
    """Calls Aerolink/Lumosel's OpenAI-COMPATIBLE endpoint instead of the
    Anthropic-shaped one _chat_call_claude_text uses — same account,
    balance, rate limits, and model catalog (confirmed via
    lumosel.vip/dashboard/documentation, 2026-08-04 admin request), just a
    different request/response shape reached over plain HTTP (this file's
    existing pattern for non-Anthropic-SDK providers, see
    _chat_call_gemini_text) rather than the anthropic SDK. Model IDs are
    Lumosel's own (e.g. "gpt-5.6", "glm-5.2") — real OpenAI model names
    like "gpt-4o" are NOT aliased and would 404.

    Not the default path — GPT/GLM/Kimi already work fine via the
    Anthropic-shaped Aerolink call. This exists as an EXTRA fallback layer
    for those same non-Claude models (their more native calling
    convention, per Lumosel's own docs) rather than a replacement, so a
    transient issue on the Anthropic-shape translation for one specific
    model has somewhere else to try before falling through to Google.
    Raises on failure, same as the other _chat_call_* helpers."""
    messages = [{"role": "assistant" if h["role"] == "model" else "user",
                 "content": h["parts"][0]["text"]} for h in history]
    _sys = _CHAT_SYSTEM_PROMPT + (f"\n\n{extra_system}" if extra_system else "")
    _keys = _aerolink_configured_keys() or [k for k in _aerolink_all_key_slots() if k]
    if not _keys:
        raise Exception("No Aerolink key configured")
    key = _keys[attempt % len(_keys)]
    r = requests.post(_LUMOSEL_OPENAI_URL,
        headers={"Authorization": f"Bearer {key}", "content-type": "application/json"},
        json={"model": model_id, "messages": [{"role": "system", "content": _sys}] + messages},
        timeout=60)
    if not r.ok:
        raise Exception(f"{r.status_code} {r.text[:300]}")
    choices = r.json().get("choices") or []
    if not choices:
        raise Exception("Empty choices in OpenAI-shape response")
    return choices[0].get("message", {}).get("content", "") or "…"

_CHAT_ROUTER_MODEL = "claude-opus-5"   # classifier for admin-action/trade-question/
# knowledge-topic/model routing (_chat_classify_combined) — via Aerolink, not
# Gemini, so per-message routing calls don't eat into Gemini's tiny 20-requests/day
# free quota on top of whatever "google" answers get picked too.
# Was "kimi-k3" (fast/cheap) until 2026-08-04 — admin explicitly chose accuracy
# over speed after repeated real misclassifications (a salary/tax question read
# as a BTC trade question, "draw" inside "withdrawal" as an image request, etc.):
# a single classifier call juggling 4 judgment calls at once is where a cheap/
# fast model's shallow pattern-matching shows up most. Replies will be a bit
# slower than the kimi-k3 era, but still just ONE classifier call (not the 3
# sequential ones from before that fix), so nowhere near as slow as that was.

def _chat_classify_model(message: str) -> str:
    """CHAT_MODEL == "auto": asks a fast/cheap model to pick which text model in
    _AEROLINK_MODEL_CATALOG should actually answer this specific message (crypto/
    trading -> Claude, coding -> GPT, etc.) — one extra API call per message, by
    admin request (2026-08-03), traded for better per-question model fit. Falls
    back to "google" (free, always available) on any failure or unparseable
    response — a bad routing call must never block the chat entirely."""
    _catalog_desc = "\n".join(f"- {mid}: {info['label']} ({info['tier']})"
        for mid, info in _AEROLINK_MODEL_CATALOG.items() if info["kind"] == "text")
    _prompt = (
        "Pick the single best AI model to answer the user message below. Reply with "
        "ONLY the model id from the list, nothing else — no punctuation, no explanation.\n\n"
        f"Available models:\n- google: Google Gemini (general-purpose, free)\n{_catalog_desc}\n\n"
        f"User message: {message}"
    )
    try:
        client = _claude_client("chat", force_aerolink=True)   # _CHAT_ROUTER_MODEL is non-Claude
        resp = client.messages.create(model=_CHAT_ROUTER_MODEL, max_tokens=20,
                                       messages=[{"role": "user", "content": _prompt}])
        _picked = (_claude_text(resp) or "").strip().split()[0].strip(".,:;\"'`").lower()
        if _picked == "google" or (_picked in _AEROLINK_MODEL_CATALOG and _AEROLINK_MODEL_CATALOG[_picked]["kind"] == "text"):
            return _picked
        print(f"  [CHAT ROUTE] unrecognized pick '{_picked}' — defaulting to google")
    except Exception as e:
        print(f"  [CHAT ROUTE] classify failed: {e}")
    return "google"

def _chat_generate_image(prompt: str):
    """Free, no-API-key image generation via Pollinations.ai (image.pollinations.ai) —
    every Gemini image model billed DIRECTLY on this account turned out to be
    billing-gated, so this is the fallback/default. GET request, image bytes come back
    directly in the response body (no JSON wrapper). Returns (text, image_bytes_or_None)."""
    import urllib.parse
    url = "https://image.pollinations.ai/prompt/" + urllib.parse.quote(prompt, safe="")
    r = requests.get(url, params={"width": 1024, "height": 1024, "nologo": "true"}, timeout=60)
    if not r.ok or not r.content:
        raise Exception(f"{r.status_code} {r.reason}")
    return "", r.content

def _chat_generate_image_aerolink(prompt: str, model_id: str):
    """Image generation via one of Aerolink's image models — these go through
    Aerolink's own key/quota rather than a directly-billed Gemini account, so the
    billing-gate issue _chat_generate_image's docstring describes doesn't apply here.
    NOTE: Aerolink's exact response shape for an image-generation model called through
    the Anthropic-style messages.create() endpoint isn't documented/confirmed here —
    this defensively scans every content block for base64 image data and raises if
    none is found, so the caller can fall back to Pollinations rather than silently
    sending nothing. Returns (text, image_bytes_or_None); raises on any failure."""
    import base64
    client = _claude_client("chat", force_aerolink=True)   # image models are never Claude
    resp = client.messages.create(
        model=model_id, max_tokens=2000,
        messages=[{"role": "user", "content": prompt}],
    )
    text_parts = []
    for block in (resp.content or []):
        _btype = getattr(block, "type", None)
        if _btype == "text":
            text_parts.append(getattr(block, "text", ""))
            continue
        # Look for base64 image data under whatever shape this block turns out
        # to have (source.data, or a direct .data/.image field) — best-effort,
        # since the exact schema Aerolink returns for image models isn't confirmed.
        _src = getattr(block, "source", None)
        _b64 = (getattr(_src, "data", None) if _src else None) or getattr(block, "data", None) or getattr(block, "image", None)
        if _b64:
            try:
                return "\n".join(text_parts).strip(), base64.b64decode(_b64)
            except Exception:
                pass
    raise Exception("No image data found in Aerolink response — unexpected format for this model")

_CHAT_GATEWAY_SWITCH_CMDS = {
    "switch direct": "direct", "switch to direct": "direct",
    "switch free": "aerolink", "switch to free": "aerolink",
}

def _extract_reply_context(msg: dict) -> str:
    """Text/caption of the message being replied to, if any (admin request
    2026-08-04) — lets /chat, PECHI, and BOKI answer questions about a
    specific message the user replied to (e.g. reply to a signal, then ask
    "what's the SL on this") instead of only ever seeing the user's own
    typed words. Empty string if this message isn't a reply, or the
    replied-to message has no readable text/caption (e.g. a bare photo)."""
    _reply_to = msg.get("reply_to_message") or {}
    return _reply_to.get("text") or _reply_to.get("caption") or ""

def _combine_reply_context(message: str, reply_context: str) -> str:
    if not reply_context:
        return message
    return f'[Replying to this message: "{reply_context.strip()}"]\n\n{message}'

def _bingx_symbol_for_base(base: str):
    """Verifies a coin base ticker (e.g. "BTC") against BingX's live
    perpetual contract list, returning the real symbol (e.g. "BTC-USDT") or
    None if it isn't actually listed — never trust a model's coin guess
    without checking it against something real."""
    if not base:
        return None
    try:
        r = requests.get("https://open-api.bingx.com/openApi/swap/v2/quote/contracts", timeout=10).json()
        all_contracts = r.get("data", [])
    except Exception as e:
        print(f"  [CHAT TRADE] contracts fetch failed: {e}")
        return None
    _bases = {c.get("symbol", "").replace("-USDT", "").upper(): c.get("symbol", "") for c in all_contracts}
    return _bases.get(base.strip().upper())

def _chat_classify_trade_intent(own_message: str, reply_context: str):
    """Reads BOTH the user's own message and whatever they replied to
    TOGETHER (admin request 2026-08-04: "read both messages, then we know
    what's being asked") to decide if this is a genuine trade question,
    which specific coin, and — critically — whether a SPECIFIC trade idea
    (direction/entry/target/SL) was actually proposed somewhere in the
    conversation that the user wants VALIDATED, rather than a generic
    "what's a good trade right now" request. Without this distinction, a
    reply-thread setup like "short BTC 64-64.5k, target 59.6k" + "tell me
    trade validity" got answered with a completely independent fresh
    recommendation that could contradict the actual idea being asked about
    (e.g. answering "long" when the question was about a proposed short).
    Uses the same fast/cheap Aerolink classifier as CHAT_MODEL=="auto"
    routing. Returns (is_trade_question: bool, symbol: str or None, setup:
    dict or None) — symbol is verified against BingX's real contract list
    via _bingx_symbol_for_base before being trusted, so a hallucinated or
    misspelled coin never gets treated as resolved."""
    _prompt = (
        "Read both messages below and decide if the user is asking for a trade/market "
        "analysis on a specific cryptocurrency, which one, and whether a SPECIFIC trade idea "
        "was proposed anywhere in this conversation that they want validated.\n\n"
        f'Replied-to message (context, may be empty): "{reply_context}"\n'
        f'User\'s actual message: "{own_message}"\n\n'
        'Reply with ONLY this exact JSON, nothing else:\n'
        '{"is_trade_question": true or false, "coin": "BTC" or null, '
        '"setup": {"direction": "LONG or SHORT", "entry": "e.g. 64000-64500 or 64200", '
        '"target": "e.g. 59600 or null", "sl": "e.g. 65500 or null"} or null}\n\n'
        "Rules:\n"
        "- is_trade_question is true ONLY if an actual cryptocurrency name or ticker (BTC, ETH, SOL, "
        "or similar) is explicitly present somewhere in either message — never infer or guess a coin "
        "just because the topic involves money, prices, percentages, or a financial-sounding "
        "calculation. Salary, tax, LPA/CTC, income, budgeting, real-world currency, or any other "
        "everyday-money question is NEVER a trade question, no matter how financial it sounds.\n"
        "- coin is the base ticker (e.g. BTC, ETH, SOL) of the SPECIFIC coin actually being "
        "asked about, using context from BOTH messages together — a reply-thread quote often "
        "clarifies which coin a short follow-up question is really about.\n"
        "- If more than one coin is mentioned, pick the one that's the actual subject of the "
        "question, not just any coin name that appears.\n"
        "- If no coin is explicitly named, both is_trade_question and coin must be false/null — no exceptions.\n"
        "- setup: fill this in ONLY if a specific direction/entry/target was actually stated "
        "somewhere in the conversation (either message) that the user wants evaluated — e.g. "
        "\"short 64-64.5k target 59.6k\". If the user is just asking for a fresh/new trade idea "
        "with no specific levels already proposed, setup must be null."
    )
    try:
        client = _claude_client("chat", force_aerolink=True)
        resp = client.messages.create(model=_CHAT_ROUTER_MODEL, max_tokens=180,
                                       messages=[{"role": "user", "content": _prompt}])
        _raw = _claude_text(resp) or ""
        _m = re.search(r'\{.*\}', _raw, re.DOTALL)
        d = json.loads(_m.group()) if _m else {}
        is_trade = bool(d.get("is_trade_question"))
        if not is_trade:
            return False, None, None
        return True, _bingx_symbol_for_base(d.get("coin")), d.get("setup") or None
    except Exception as e:
        print(f"  [CHAT TRADE] classify failed: {e}")
        return False, None, None

def _boki_run(cid, sender_id, command_text: str):
    """Runs a REAL bot command exactly as if the admin had typed it — same
    validation, same save_settings(), same confirmation reply already built
    into that command's own handler. This is the reuse trick behind almost
    every action in _ADMIN_ACTIONS below: there is no duplicate settings
    logic here to drift out of sync with the real command over time — the
    callback dispatcher itself already leans on this same trick for a
    couple of buttons (e.g. directnu:, gateway:). sender_id must be the
    REAL admin Telegram user id (not the chat id) so this still passes
    handle_command's admin check when used from inside a group."""
    handle_command(command_text, cid, {}, sender_id=sender_id)

def _boki_onoff(word: str):
    w = (word or "").strip().lower()
    if w in ("on", "true", "yes", "enable", "enabled"): return "on"
    if w in ("off", "false", "no", "disable", "disabled"): return "off"
    return None

def _boki_norm_scankind(word: str):
    """Maps loose scan-type words to the canonical key used across the
    grid-style settings below (scan1/scan2/test1/test2/btc) — TS1/TS2 and
    demo1/demo2 are the SAME slots under two different naming conventions
    used in different corners of this bot (AICFG_GRID vs win-rate
    thresholds), so both are accepted here."""
    return {
        "scan1": "scan1", "s1": "scan1",
        "scan2": "scan2", "s2": "scan2",
        "ts1": "test1", "test1": "test1", "demo1": "test1",
        "ts2": "test2", "test2": "test2", "demo2": "test2",
        "btc": "btc",
    }.get((word or "").strip().lower())

def _boki_norm_tier(word: str):
    return {"verified": "verified", "unverified": "unverified",
            "nonspecial": "nonspecial", "normal": "nonspecial"}.get((word or "").strip().lower())

def _boki_norm_model_registry(word: str):
    """Maps a loose model word to an actual MODEL_REGISTRY key — the small
    admin-curated list /aiconfig's grid actually offers (default: Opus 5,
    Fable 5, Opus 4.8, plus anything added via /addmodel), NOT the larger
    _AEROLINK_MODEL_CATALOG used by /model and /chatmodel. Never trusts a
    value it can't map to something real — returns None rather than
    guessing, same principle as _bingx_symbol_for_base for coins."""
    w = (word or "").strip().lower()
    if not w:
        return None
    for mid in MODEL_REGISTRY:
        if w == mid.lower():
            return mid
    for mid, tag in MODEL_REGISTRY.items():
        if w == tag.lower() or w == f"opus{tag}".lower():
            return mid
    _aliases = {"opus": "claude-opus-5", "opus5": "claude-opus-5",
                "fable": "claude-fable-5", "fable5": "claude-fable-5",
                "4.8": "claude-opus-4-8", "48": "claude-opus-4-8", "4-8": "claude-opus-4-8"}
    _mid = _aliases.get(w)
    return _mid if _mid in MODEL_REGISTRY else None

