def _chat_classify_admin_action(own_message: str, reply_context: str):
    """Single unified classifier covering every live admin action Boki/Pechi
    can actually execute (2026-08-04 — replaced the earlier key-only
    classifier after the admin asked for full command/button coverage: "train
    boki/pechi to execute every possible request ... if anything new or
    unable to understand ask admin"). Reads the whole _ADMIN_ACTIONS catalog
    as its menu and picks AT MOST ONE matching action, or none — never
    invents an action id that isn't in the catalog. Returns (action_id: str
    or None, value: str)."""
    _catalog = "\n".join(f"- {aid}: {info['desc']}" for aid, info in _ADMIN_ACTIONS.items())
    _prompt = (
        "You are deciding whether an admin's message is a request to change a LIVE setting "
        "or trigger a LIVE action on their trading bot, and if so, which ONE of the actions "
        "below it matches.\n\n"
        f'Replied-to message (context, may be empty): "{reply_context}"\n'
        f'Admin\'s actual message: "{own_message}"\n\n'
        "AVAILABLE ACTIONS:\n" + _catalog + "\n\n"
        'Reply with ONLY this exact JSON, nothing else:\n'
        '{"action": "<one of the action ids above>" or null, "value": "<the value string described for that action, or empty>"}\n\n'
        "Rules:\n"
        "- action must be null unless the message is CLEARLY asking to change one specific "
        "live setting/action from the list — not a question about it, not a casual mention.\n"
        "- Only ever use an action id that's actually in the list above.\n"
        "- Follow each action's value format instructions exactly, including any shorthand "
        "normalization it describes.\n"
        "- If it's ambiguous which action is meant, or it could plausibly match more than one "
        "action, action must be null — never guess between two real actions."
    )
    try:
        client = _claude_client("chat", force_aerolink=True)
        resp = client.messages.create(model=_CHAT_ROUTER_MODEL, max_tokens=200,
                                       messages=[{"role": "user", "content": _prompt}])
        _raw = _claude_text(resp) or ""
        _m = re.search(r'\{.*\}', _raw, re.DOTALL)
        d = json.loads(_m.group()) if _m else {}
        _action = d.get("action")
        if _action not in _ADMIN_ACTIONS:
            return None, ""
        return _action, (d.get("value") or "").strip()
    except Exception as e:
        print(f"  [CHAT ADMIN ACTION] classify failed: {e}")
        return None, ""

def _chat_dispatch_admin_action(cid, sender_id, is_admin: bool, action_id, value: str) -> bool:
    """Dispatch-only half of the admin-action flow — the classify step now
    happens ONCE in _chat_classify_combined() (2026-08-04 perf fix: Pechi/
    Boki/chat used to each run 3 separate sequential classifier calls
    before generating any reply — admin-action, trade-intent, best-model
    routing — which is what an admin reported as "boki... nothing
    happening... taking some time to reply"; it was never actually stuck,
    just paying for 3 round-trips in a row before replying at all).
    Every executor either performs the REAL change (reusing the exact same
    handle_command()/save_settings() path the real command or button uses)
    and sends its own confirmation, or returns a short clarifying question
    when it can't tell exactly what's meant — never a guess, per the
    admin's "if unable to understand, ask admin" requirement. Actions in
    _ADMIN_RISKY_ACTIONS go through _boki_ask_confirm first instead of
    firing immediately. Returns True if action_id was handled."""
    if not is_admin or action_id is None:
        return False
    _sid = sender_id if sender_id is not None else cid
    _fn = _ADMIN_ACTIONS[action_id]["exec"]
    _clarify = _fn(cid, _sid, value, _confirmed=False) if action_id in _ADMIN_RISKY_ACTIONS else _fn(cid, _sid, value)
    if _clarify:
        send_reply(cid, f"🤔 {_clarify}", skip_smallcaps=True)
    return True

def _chat_try_admin_action(cid, own_message: str, is_admin: bool, sender_id=None, reply_context: str = "") -> bool:
    """Standalone classify+dispatch — kept for any caller that wants the
    old one-shot behavior; the hot paths (PECHI/BOKI/chat) now call
    _chat_classify_combined() once and use _chat_dispatch_admin_action
    directly instead, to avoid paying for this classifier twice."""
    if not is_admin:
        return False
    action_id, value = _chat_classify_admin_action(own_message, reply_context)
    return _chat_dispatch_admin_action(cid, sender_id, is_admin, action_id, value)

def _chat_dispatch_trade_analysis(cid, is_admin: bool, sym, setup) -> bool:
    """Dispatch-only half of the trade-analysis flow — see
    _chat_dispatch_admin_action's docstring for why classify and dispatch
    are now split. If a specific setup was proposed: evaluates THAT idea
    against real current price/structure (_coin_validate_setup_data /
    _chat_format_setup_validation) — e.g. "short 64-64.5k target 59.6k"
    gets judged as still-pending/valid/invalidated based on where price
    actually is, never answered with an unrelated fresh recommendation
    that could flatly contradict the idea being asked about. Otherwise:
    runs the SAME live-data pipeline /coin uses (_coin_analysis_data: real
    BingX price/24h range/volume + SCAN_MODEL) to propose a fresh idea,
    formatted for chat (_chat_format_trade_analysis) rather than /coin's
    own boxed dashboard style. Returns True if sym was handled."""
    if not is_admin or not sym:
        return False
    send_reply(cid, f"🧠 Fetching live <b>{sym.replace('-','/')}</b> data from BingX and analyzing...", skip_smallcaps=True)
    def _run():
        try:
            if setup:
                v = _coin_validate_setup_data(sym, setup)
                send_reply(cid, _chat_format_setup_validation(v), skip_smallcaps=True)
            else:
                a = _coin_analysis_data(sym, "MARKET")
                send_reply(cid, _chat_format_trade_analysis(a), skip_smallcaps=True)
        except Exception as e:
            print(f"  [CHAT TRADE] {cid}: {e}")
            send_reply(cid, f"⚠️ Couldn't analyze {sym.replace('-','/')} right now — try again.", skip_smallcaps=True)
    threading.Thread(target=_run, daemon=True).start()
    return True

def _chat_try_trade_analysis(cid, own_message: str, is_admin: bool, reply_context: str = "") -> bool:
    """Standalone classify+dispatch — kept for any caller that wants the
    old one-shot behavior; the hot paths now call _chat_classify_combined()
    once and use _chat_dispatch_trade_analysis directly instead."""
    if not is_admin:
        return False
    is_trade, sym, setup = _chat_classify_trade_intent(own_message, reply_context)
    if not is_trade:
        return False
    return _chat_dispatch_trade_analysis(cid, is_admin, sym, setup)

def _chat_classify_combined(own_message: str, reply_context: str, is_admin: bool):
    """Single classifier call that replaces THREE separate sequential ones
    (admin action, trade intent, best-model routing) for a single message —
    was the real cause behind an admin report that read as "boki... nothing
    happening" but turned out to just be slow: every Pechi/Boki/chat
    message was paying for 3 full API round-trips back-to-back before even
    starting to generate the actual reply (2026-08-04 perf fix). Skips the
    admin-action catalog entirely in the prompt when is_admin is False, so
    a regular user's prompt stays small. Also picks 0-3 relevant knowledge
    topics (see _KNOWLEDGE_TOPICS) when the message is asking HOW some
    bot-internal system works, so _admin_chat_context() can splice in real
    grounded detail instead of the model guessing (2026-08-04, after Boki
    fabricated a wrong explanation of verified/unverified). Also writes a
    short context_note — this classifier already runs on the strongest
    model (claude-opus-5) and already reads both messages together, so
    rather than spend that understanding on just a handful of terse labels,
    it also hands whichever model ends up answering (which might be a
    cheaper/faster one) a 1-2 sentence briefing on what's actually being
    asked, accounting for the reply-thread context. Admin's own idea
    (2026-08-04): "take everything... use most powerful model then analyze
    it, make prompt, then top model for it then answer" — one call instead
    of two, since the classifier already has to read everything anyway.
    Returns a dict:
    {"admin_action": id or None, "admin_value": str,
     "is_trade_question": bool, "coin": verified symbol or None,
     "setup": dict or None, "best_model": model id or "google",
     "topics": [topic ids], "context_note": str}"""
    _catalog = ""
    _topics_block = ""
    if is_admin:
        _catalog = ("\n\nADMIN LIVE-ACTION CATALOG (only relevant if the message is CLEARLY asking to "
                     "change a live setting or trigger a live action — not a question about one, not a "
                     "casual mention):\n" + "\n".join(f"- {aid}: {info['desc']}" for aid, info in _ADMIN_ACTIONS.items()))
        _topics_block = ("\n\nKNOWLEDGE TOPICS (pick 0-3 that are relevant ONLY if the message is asking "
                          "HOW some bot-internal system actually works, e.g. \"how does X become verified\", "
                          "\"how does copytrade work\" — not for simple where-is-the-button questions, not "
                          "for admin actions, not for trade questions):\n" +
                          "\n".join(f"- {tid}: {desc}" for tid, desc in _KNOWLEDGE_TOPICS.items()))
    _model_catalog = "\n".join(f"- {mid}: {info['label']} ({info['tier']})"
        for mid, info in _AEROLINK_MODEL_CATALOG.items() if info["kind"] == "text")
    _prompt = (
        "Read both messages below and answer FIVE independent questions about them in one JSON object.\n\n"
        f'Replied-to message (context, may be empty): "{reply_context}"\n'
        f'User\'s actual message: "{own_message}"'
        + _catalog + _topics_block + "\n\n"
        'Reply with ONLY this exact JSON, nothing else:\n'
        '{"admin_action": "<action id>" or null, "admin_value": "<value string for that action, or empty>", '
        '"is_trade_question": true or false, "coin": "BTC" or null, '
        '"setup": {"direction": "LONG or SHORT", "entry": "e.g. 64000-64500 or 64200", '
        '"target": "e.g. 59600 or null", "sl": "e.g. 65500 or null"} or null, '
        '"best_model": "<a model id from the list below, or \\"google\\">", '
        '"topics": ["<topic id>", ...] or [], '
        '"context_note": "<1-2 plain sentences: what is this person ACTUALLY asking, once you account for '
        'the reply-thread context and any ambiguity in the wording — written as a briefing for another AI '
        'that will write the actual reply, or empty string if it is a simple/obvious message needing no '
        'extra framing>"}\n\n'
        "Rules:\n"
        "1. admin_action must be null unless the message is CLEARLY asking to change, run, or VIEW/SHOW "
        "one specific live setting, action, or piece of real data (e.g. \"show my verified times\" is a "
        "real request for live data, not a casual question)" + (" from the catalog above; only ever use an id that's actually listed" if is_admin else " (there is no catalog here, so this must always be null)") + ". "
        "If ambiguous or it could match more than one action, null — never guess.\n"
        "2. is_trade_question is true ONLY if an actual cryptocurrency name or ticker (BTC, ETH, SOL, or "
        "similar) is explicitly present somewhere in either message — never infer or guess a coin just "
        "because the topic involves money, prices, percentages, or a financial-sounding calculation. "
        "Salary, tax, LPA/CTC, income, budgeting, real-world currency, or any other everyday-money "
        "question is NEVER a trade question and coin must stay null even if numbers or \"%\" appear — "
        "these have nothing to do with crypto no matter how financial they sound. coin is the base ticker "
        "(e.g. BTC, ETH, SOL) of the coin actually named, using context from BOTH messages together. If "
        "more than one coin is mentioned, pick the one that's the actual subject. If no specific coin is "
        "explicitly named, both is_trade_question and coin must be false/null — no exceptions. setup is "
        "filled in ONLY if a specific direction/entry/target was actually stated somewhere in the "
        "conversation that the user wants evaluated — otherwise null.\n"
        "3. best_model: pick the single best model to answer this message in general (used only when it's "
        "neither an admin action nor a trade question) — crypto/trading talk suits a capable reasoning "
        "model, coding suits a code-strong model, casual chat can use anything.\n"
        "4. topics: only ever use ids actually listed above; empty list unless the message is genuinely "
        "asking how something works.\n"
        "5. context_note: only fill this in when reading BOTH messages together actually clarifies "
        "something a second AI, seeing only the raw text, could otherwise misread (a short/ambiguous "
        "follow-up whose real subject is in the reply-thread, a message that could look like it's about "
        "one topic but is actually about another, slang/shorthand worth spelling out). Leave it empty for "
        "a plain, self-contained message — don't manufacture a summary just to fill the field.\n"
        f"Models available for best_model:\n- google: Google Gemini (general-purpose, free)\n{_model_catalog}"
    )
    try:
        client = _claude_client("chat", force_aerolink=True)
        resp = client.messages.create(model=_CHAT_ROUTER_MODEL, max_tokens=400,
                                       messages=[{"role": "user", "content": _prompt}])
        _raw = _claude_text(resp) or ""
        _m = re.search(r'\{.*\}', _raw, re.DOTALL)
        d = json.loads(_m.group()) if _m else {}
        _action = d.get("admin_action") if is_admin else None
        if _action not in _ADMIN_ACTIONS:
            _action = None
        _is_trade = bool(d.get("is_trade_question"))
        _coin = _bingx_symbol_for_base(d.get("coin")) if _is_trade else None
        _model = (d.get("best_model") or "google").strip().lower()
        if not (_model == "google" or (_model in _AEROLINK_MODEL_CATALOG and _AEROLINK_MODEL_CATALOG[_model]["kind"] == "text")):
            _model = "google"
        _topics = [t for t in (d.get("topics") or []) if is_admin and t in _KNOWLEDGE_TOPICS][:3]
        return {"admin_action": _action, "admin_value": (d.get("admin_value") or "").strip() if _action else "",
                "is_trade_question": _is_trade, "coin": _coin, "setup": d.get("setup") if (_is_trade and _coin) else None,
                "best_model": _model, "topics": _topics, "context_note": (d.get("context_note") or "").strip()}
    except Exception as e:
        print(f"  [CHAT COMBINED] classify failed: {e}")
        return {"admin_action": None, "admin_value": "", "is_trade_question": False, "coin": None,
                "setup": None, "best_model": "google", "topics": [], "context_note": ""}

def _strip_trigger_word(text: str, word: str):
    """Shared prefix-detector for PECHI/BOKI-style trigger words — a message
    starting with `word` (any case, optionally followed by a space/colon/
    comma/dash) has that prefix stripped. Returns (rest_of_message, True) if
    detected, else (original_text, False)."""
    _stripped = text.lstrip()
    _lower = _stripped.lower()
    if _lower == word or any(_lower.startswith(f"{word}{sep}") for sep in (" ", ":", ",", "-")):
        return _stripped[len(word):].lstrip(" :,-").strip(), True
    return text, False

def _pechi_strip(text: str):
    """PECHI trigger (admin-only, 2026-08-03 request): a message prefixed
    with "pechi" (any case, e.g. "Pechi generate a image of cow") always
    gets the best model for THAT message and tries the free Aerolink
    gateway first, falling back to Direct/Google automatically on any
    failure — see _chat_pechi_text_reply. Returns (message_with_prefix_
    removed, True) if detected, else (original_text, False)."""
    return _strip_trigger_word(text, "pechi")

def _boki_strip(text: str):
    """BOKI trigger (admin-only, 2026-08-04 request): same standalone
    pattern as PECHI, but NEVER falls back to the paid Direct API — only
    ever uses free options (Aerolink or Google). See _chat_boki_text_reply."""
    return _strip_trigger_word(text, "boki")

def _chat_pechi_text_reply(history: list, message: str, extra_system: str = "", precomputed_model: str = None) -> str:
    """Best-model-for-this-message, free-first-then-fallback text reply for
    a PECHI-tagged message. Classifies via the same router used for
    CHAT_MODEL=="auto", tries Aerolink first regardless of the session's own
    gateway setting. Full fallback chain so a single provider's outage or
    quota (Google's free tier is a famously tiny 5 RPM/20 RPD) can never be
    a dead end: Aerolink (Anthropic-shape) -> Aerolink (OpenAI-shape, non-
    Claude models only) -> Direct (if Claude) -> Google -> Direct Claude as
    a last resort. Only raises if every one of those genuinely fails.

    precomputed_model: skips the classify call when the caller already got
    a model pick from _chat_classify_combined() — avoids paying for the
    same classification twice per message (2026-08-04 perf fix)."""
    _model = precomputed_model or _chat_classify_model(message)
    if _model != "google":
        try:
            return _chat_call_claude_text(history, _model, extra_system=extra_system, gateway_override="aerolink")
        except Exception as e:
            print(f"  [PECHI] free (Aerolink) attempt with {_model} failed ({e}) — falling back")
            if not _is_claude_model(_model):
                try:
                    return _chat_call_openai_shape(history, _model, extra_system=extra_system)
                except Exception as e_oa:
                    print(f"  [PECHI] Aerolink OpenAI-shape with {_model} also failed ({e_oa}) — trying Google")
            if _is_claude_model(_model):
                try:
                    return _chat_call_claude_text(history, _model, extra_system=extra_system, gateway_override="direct")
                except Exception as e2:
                    print(f"  [PECHI] Direct fallback with {_model} also failed ({e2}) — trying Google")
    try:
        return _chat_call_gemini_text(history, extra_system=extra_system)
    except Exception as e3:
        print(f"  [PECHI] Google also failed ({e3}) — final fallback to Direct Claude")
        return _chat_call_claude_text(history, "claude-sonnet-5", extra_system=extra_system, gateway_override="direct")

def _chat_boki_text_reply(history: list, message: str, extra_system: str = "", precomputed_model: str = None) -> str:
    """BOKI trigger (admin-only, standalone, 2026-08-04): same best-model
    classification as PECHI, but ONLY ever uses free options (Aerolink or
    Google Gemini) — never falls back to the paid Direct/Anthropic API,
    even if the free Aerolink attempt fails. For non-Claude models, tries
    Aerolink's OpenAI-compatible endpoint (still the same free Aerolink
    account, just the other calling shape) before giving up to Google.

    precomputed_model: see _chat_pechi_text_reply's docstring."""
    _model = precomputed_model or _chat_classify_model(message)
    if _model == "google":
        return _chat_call_gemini_text(history, extra_system=extra_system)
    try:
        return _chat_call_claude_text(history, _model, extra_system=extra_system, gateway_override="aerolink")
    except Exception as e:
        print(f"  [BOKI] free (Aerolink) attempt with {_model} failed ({e}) — falling back")
        if not _is_claude_model(_model):
            try:
                return _chat_call_openai_shape(history, _model, extra_system=extra_system)
            except Exception as e_oa:
                print(f"  [BOKI] Aerolink OpenAI-shape with {_model} also failed ({e_oa}) — trying Google")
        return _chat_call_gemini_text(history, extra_system=extra_system)

def _handle_standalone_trigger(cid, message: str, text_reply_fn, tag: str, reply_context: str = "", sender_id=None):
    """Shared standalone (no /chat session) handler for PECHI/BOKI-style
    trigger words — image path is identical for both (best image model
    first, Pollinations fallback; Direct/Anthropic has no image generation
    at all, so there's nothing gateway-specific to differ there). Only the
    text-reply function differs between triggers (see text_reply_fn).

    reply_context: text of the message being replied to, if any (see
    _extract_reply_context) — only folded into the TEXT path, not image
    prompts, so a reply's content can't accidentally pollute an image
    generation prompt.

    sender_id: the REAL admin Telegram user id, threaded through to
    _chat_try_admin_action so executed commands pass handle_command's
    admin check correctly even when PECHI/BOKI is used inside a group
    (where cid is the group, not the admin's own id)."""
    _is_image = _chat_is_image_request(message)
    try:
        if _is_image:
            send_reply(cid, "🎨 Generating image…")
            if CHAT_IMAGE_MODEL != "pollinations":
                try:
                    reply_text, img_bytes = _chat_generate_image_aerolink(message, CHAT_IMAGE_MODEL)
                except Exception as _aie:
                    print(f"  [{tag} IMAGE] Aerolink model {CHAT_IMAGE_MODEL} failed ({_aie}) — falling back to Pollinations")
                    reply_text, img_bytes = _chat_generate_image(message)
            else:
                reply_text, img_bytes = _chat_generate_image(message)
            if img_bytes:
                requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendPhoto",
                    data={"chat_id": cid, "caption": reply_text[:1024] if reply_text else ""},
                    files={"photo": ("image.png", img_bytes, "image/png")}, timeout=30)
            else:
                send_reply(cid, reply_text or "⚠️ Couldn't generate that image, try rephrasing.", skip_smallcaps=True)
        else:
            _ai_message = _combine_reply_context(message, reply_context)
            # PECHI/BOKI are already admin-gated at the dispatcher, so this is
            # always the admin here. ONE combined classify call instead of
            # three separate ones (admin action + trade intent + best model)
            # — see _chat_classify_combined's docstring.
            _c = _chat_classify_combined(message, reply_context, is_admin=True)
            if _chat_dispatch_admin_action(cid, sender_id, True, _c["admin_action"], _c["admin_value"]):
                return
            if _chat_dispatch_trade_analysis(cid, True, _c["coin"], _c["setup"]):
                return
            _history = [{"role": "user", "parts": [{"text": _ai_message}]}]
            # context_note: a briefing from the (stronger) classifier model on
            # what's actually being asked, handed to whichever model answers —
            # see _chat_classify_combined's docstring for why.
            _note = f"WHAT THEY'RE ACTUALLY ASKING (from message analysis): {_c['context_note']}\n\n" if _c["context_note"] else ""
            reply_text = text_reply_fn(_history, _ai_message, extra_system=_note + _admin_chat_context(topics=_c["topics"]),
                                        precomputed_model=_c["best_model"])
            send_reply(cid, reply_text, skip_smallcaps=True)
    except Exception as e:
        print(f"  [{tag}] {cid}: {e}")
        send_reply(cid, f"⚠️ {tag.title()} had an error — try again.")

def _handle_pechi_standalone(cid, message: str, reply_context: str = "", sender_id=None):
    """PECHI works on its own, without ever running /chat first (admin
    request 2026-08-03) — no session, no history kept, just a single
    question -> single answer. Called directly from the command listener
    whenever an admin message starts with "pechi", regardless of whether a
    /chat session exists or this is a private chat vs a group. Best model
    for the message, free (Aerolink) first, falls back to Direct/Google on
    failure — see _chat_pechi_text_reply."""
    _handle_standalone_trigger(cid, message, _chat_pechi_text_reply, "PECHI", reply_context=reply_context, sender_id=sender_id)

def _handle_boki_standalone(cid, message: str, reply_context: str = "", sender_id=None):
    """BOKI (admin-only, standalone, 2026-08-04): same standalone pattern as
    PECHI, but NEVER uses the paid Direct/Anthropic API, even on failure —
    only Aerolink or Google, both free. See _chat_boki_text_reply."""
    _handle_standalone_trigger(cid, message, _chat_boki_text_reply, "BOKI", reply_context=reply_context, sender_id=sender_id)

def _handle_chat_message(cid, text: str, sender_id=None, reply_context: str = ""):
    sess = _chat_sessions.get(str(cid))
    if not sess:
        return
    sess["last"] = time.time()
    # Admin-only features (PECHI, gateway switching, personal-assistant context)
    # must key off WHO actually sent this message, not which chat it landed in —
    # in a group, cid is the group's own id, never ADMIN_CHAT_ID, even when the
    # admin is the one replying. sender_id (falls back to cid for old callers)
    # is the real Telegram user id, correct in both private chats and groups.
    _is_admin_cid = bool(ADMIN_CHAT_ID and str(sender_id if sender_id is not None else cid) == str(ADMIN_CHAT_ID))
    # In-session gateway switch (admin-only, 2026-08-03 request) — typing
    # "switch direct" or "switch free" changes this ONE session's Claude
    # gateway (Direct vs Aerolink's free-tier keys) without touching the
    # global CHAT_USE_AEROLINK default or the scan engine's own USE_AEROLINK.
    # Intercepted here, before any AI call, so it never gets sent as a real
    # chat message — resets automatically on /endchat or session timeout
    # since it's just a key in this session's own dict, not persisted.
    _norm_cmd = text.strip().lower().strip("[]").strip()
    if _is_admin_cid and _norm_cmd in _CHAT_GATEWAY_SWITCH_CMDS:
        sess["gateway"] = _CHAT_GATEWAY_SWITCH_CMDS[_norm_cmd]
        _gw_label = "Direct" if sess["gateway"] == "direct" else "Aerolink (free)"
        send_reply(cid, f"✅ Gateway switched to <b>{_gw_label}</b> for this chat session.\n"
                         f"<i>(Only affects Claude-model replies — non-Claude models always use Aerolink regardless.)</i>")
        return
    text, _is_pechi = _pechi_strip(text) if _is_admin_cid else (text, False)
    _is_image = _chat_is_image_request(text)
    if not _is_image and CHAT_MODEL == "google" and not GEMINI_API_KEY:
        send_reply(cid, "⚠️ Chat AI isn't configured yet — admin needs to set GEMINI_API_KEY.")
        return
    try:
        if _is_image:
            send_reply(cid, "🎨 Generating image…")
            if CHAT_IMAGE_MODEL != "pollinations":
                try:
                    reply_text, img_bytes = _chat_generate_image_aerolink(text, CHAT_IMAGE_MODEL)
                except Exception as _aie:
                    print(f"  [CHAT IMAGE] Aerolink model {CHAT_IMAGE_MODEL} failed ({_aie}) — falling back to Pollinations")
                    reply_text, img_bytes = _chat_generate_image(text)
            else:
                reply_text, img_bytes = _chat_generate_image(text)
            if img_bytes:
                requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendPhoto",
                    data={"chat_id": cid, "caption": reply_text[:1024] if reply_text else ""},
                    files={"photo": ("image.png", img_bytes, "image/png")}, timeout=30)
            else:
                send_reply(cid, reply_text or "⚠️ Couldn't generate that image, try rephrasing.", skip_smallcaps=True)
            sess["history"].append({"role": "user", "parts": [{"text": text}]})
            sess["history"].append({"role": "model", "parts": [{"text": reply_text or "[sent an image]"}]})
        else:
            # ONE combined classify call instead of up to three separate
            # sequential ones (admin action + trade intent + best-model
            # routing) — see _chat_classify_combined's docstring for why
            # this matters (an admin report of "boki... nothing happening"
            # that turned out to just be paying for 3 round-trips in a row).
            _c = _chat_classify_combined(text, reply_context, is_admin=_is_admin_cid)
            if _chat_dispatch_admin_action(cid, sender_id, _is_admin_cid, _c["admin_action"], _c["admin_value"]):
                # Live admin control request — executed directly against the
                # real bot action, not a normal conversational reply.
                sess["history"].append({"role": "user", "parts": [{"text": text}]})
                sess["history"].append({"role": "model", "parts": [{"text": "[executed a live admin action]"}]})
            elif _chat_dispatch_trade_analysis(cid, _is_admin_cid, _c["coin"], _c["setup"]):
                # Real trade question about a specific coin (2026-08-04 request) —
                # handled entirely by _do_coin_analysis's live-BingX-data pipeline,
                # not a normal conversational reply. Still logged into history so
                # follow-up chat messages have some record this happened.
                sess["history"].append({"role": "user", "parts": [{"text": text}]})
                sess["history"].append({"role": "model", "parts": [{"text": "[ran a live BingX trade analysis]"}]})
            else:
                # Folds in the replied-to message's text (if any — see
                # _extract_reply_context), so "reply to a signal, then ask
                # what's the SL on this" actually has something to answer from.
                _ai_text = _combine_reply_context(text, reply_context)
                sess["history"].append({"role": "user", "parts": [{"text": _ai_text}]})
                # Admin-only personal-assistant context (2026-08-03 request) — never
                # injected for a regular user's session. context_note (a briefing
                # from the classifier model on what's actually being asked) applies
                # to everyone, admin or not — see _chat_classify_combined's docstring.
                _note = f"WHAT THEY'RE ACTUALLY ASKING (from message analysis): {_c['context_note']}\n\n" if _c["context_note"] else ""
                _extra_ctx = _note + (_admin_chat_context(topics=_c["topics"]) if _is_admin_cid else "")
                if _is_pechi:
                    reply_text = _chat_pechi_text_reply(sess["history"], _ai_text, extra_system=_extra_ctx,
                                                          precomputed_model=_c["best_model"])
                else:
                    _active_model = CHAT_MODEL
                    if CHAT_MODEL == "auto":
                        _active_model = _c["best_model"]  # reuse the combined classify's pick, don't re-classify
                        print(f"  [CHAT ROUTE] '{_ai_text[:60]}' -> {_active_model}")
                    if _active_model != "google":
                        reply_text = _chat_call_claude_text(sess["history"], _active_model, extra_system=_extra_ctx,
                                                             gateway_override=sess.get("gateway"))
                    else:
                        reply_text = _chat_call_gemini_text(sess["history"], extra_system=_extra_ctx)
                sess["history"].append({"role": "model", "parts": [{"text": reply_text}]})
                send_reply(cid, reply_text, skip_smallcaps=True)
        # Trim history to bound token usage
        max_msgs = _CHAT_HISTORY_MAX_TURNS * 2
        if len(sess["history"]) > max_msgs:
            sess["history"] = sess["history"][-max_msgs:]
    except Exception as e:
        print(f"  [CHAT] {cid}: {e}")
        if "429" in str(e):
            send_reply(cid, "⚠️ Chat AI hit today's free-tier limit (this model only allows a small number of replies per day). Try again later, or ask admin to switch to a higher-quota model.")
        else:
            send_reply(cid, "⚠️ Chat AI had an error — try again.")

def _chat_session_sweep_loop():
    """Background thread — closes any chat session idle for 5+ minutes and notifies the user."""
    while True:
        try:
            now = time.time()
            for cid_str in list(_chat_sessions.keys()):
                if now - _chat_sessions[cid_str]["last"] > _CHAT_TIMEOUT_SEC:
                    del _chat_sessions[cid_str]
                    try:
                        send_reply(int(cid_str), "💬 Chat session closed (5 min of inactivity).")
                    except Exception as e:
                        print(f"  [CHAT SWEEP] notify {cid_str}: {e}")
        except Exception as e:
            print(f"  [CHAT SWEEP] {e}")
        time.sleep(20)
