def _handle_liquidation_msg(raw: str):
    global _last_liq_post_time, latest_news_context
    if not SEND_NEWS:
        return
    try:
        d = json.loads(raw)
        if not str(d.get("topic", "")).startswith("allLiquidation."):
            return  # subscribe ack / pong / other control frame, not a liquidation
        for item in d.get("data", []):
            sym   = item.get("s", "?")
            side  = item.get("S", "?")          # side of the liquidation order itself: Buy/Sell
            price = float(item.get("p", 0) or 0)
            qty   = float(item.get("v", 0) or 0)
            usd   = price * qty
            if usd < LIQUIDATION_MIN_USD:
                continue
            now = time.time()
            if now - _last_liq_post_time < LIQUIDATION_POST_COOLDOWN:
                continue
            # Sell-side liquidation order = a LONG position got force-closed (bearish);
            # Buy-side liquidation order = a SHORT position got force-closed (bullish).
            if side.upper() == "SELL":
                impact, emoji, closed = "BEARISH", "🔴", "LONG"
            else:
                impact, emoji, closed = "BULLISH", "🟢", "SHORT"
            # $-scale label that doesn't collapse small liquidations to "0.00M"
            usd_label = f"{usd/1e6:,.2f}M" if usd >= 1_000_000 else \
                        f"{usd/1e3:,.1f}K" if usd >= 1_000 else f"{usd:,.0f}"
            # Coin-qty formatter — :,.4g silently switches to scientific
            # notation (e.g. "1.83e+04") once a number needs 5+ digits, which
            # is exactly the range most liquidation sizes fall in.
            qty_label = f"{qty:,.2f}" if qty >= 1 else f"{qty:.6f}".rstrip("0").rstrip(".")
            title = f"{usd_label} {sym} {closed} liquidated"
            msg_text = (
                f"<b>TRENDING INSIGHT</b>\n\n{emoji} <b>{impact}</b>\n"
                f"<b>{title}</b>\n\n"
                f"💥 {closed} position force-closed\n"
                f"💰 Size: <code>{qty_label} {sym.replace('USDT','')}</code> (${usd:,.0f})\n"
                f"💵 Price: <code>{price:,.4g}</code>"
            )
            send_to_tier_channels(msg_text, share_free=False)
            _last_liq_post_time = now
            latest_news_context = ([f"• {impact}: {title}"] + latest_news_context)[:3]
    except Exception as e:
        print(f"  [LIQUIDATION] parse/post error: {e}")

def _liquidation_ws_loop():
    """Runs forever in a background thread — reconnects automatically on drop.
    Bybit's public linear-perp stream requires an app-level ping every ~20s to
    stay alive (unlike Binance, which needed none), so the read timeout below
    doubles as the ping clock instead of just being a dead-connection guard."""
    if not HAS_WEBSOCKET:
        print("  [LIQUIDATION] websocket-client not installed — feed disabled"); return
    url = "wss://stream.bybit.com/v5/public/linear"
    _liq_topics = [f"allLiquidation.{s}" for s in _BYBIT_LIQ_SYMBOLS]
    while True:
        try:
            ws = _ws_client.create_connection(url, timeout=15)
            # One subscribe request has a ~21,000-char args limit — chunk into
            # batches of 300 (well under that even for the longest symbols)
            # instead of risking one oversized request for the full list.
            _CHUNK = 300
            for i in range(0, len(_liq_topics), _CHUNK):
                ws.send(json.dumps({"op": "subscribe", "args": _liq_topics[i:i+_CHUNK]}))
            print(f"  [LIQUIDATION] connected ({len(_liq_topics)} symbols)")
            _last_ping = time.time()
            while True:
                try:
                    msg = ws.recv()
                except Exception as _recv_e:
                    # A plain 15s read timeout just means no message arrived
                    # during a quiet stretch — keep this same connection alive
                    # instead of tearing it down. Only a real socket/connection
                    # error should fall through to the outer except.
                    if "timed out" in str(_recv_e).lower():
                        msg = None
                    else:
                        raise
                if time.time() - _last_ping >= 20:
                    ws.send(json.dumps({"op": "ping"}))
                    _last_ping = time.time()
                if msg:
                    _handle_liquidation_msg(msg)
        except Exception as e:
            print(f"  [LIQUIDATION] connection error: {e} — reconnecting in 10s")
        time.sleep(10)

# OKX liquidation feed — added alongside Bybit for wider coverage. UNLIKE
# Bybit/Binance, OKX's payload reports size in CONTRACTS (the "sz" field),
# not raw coin quantity — converting that to a real dollar figure needs each
# instrument's contract face-value multiplier (ctVal x ctMult), which comes
# from OKX's REST instrument list. Every OKX REST domain (www.okx.com,
# aws.okx.com) was unreachable from this coding sandbox (even a direct-IP
# connection via --resolve times out at the TCP level, not just DNS) — but
# that's a restriction on THIS sandbox's outbound network, not necessarily on
# Railway, which already proved it CAN reach OKX's WebSocket fine. So this
# tries the same REST fetch live from the server itself, caches it, and uses
# real dollar figures (same LIQUIDATION_MIN_USD threshold as Bybit, same
# message format) whenever it succeeds — falling back to raw contract count
# (clearly labeled, floor of OKX_LIQ_MIN_CONTRACTS) only for instruments
# where the fetch failed or a symbol's multiplier wasn't found.
OKX_LIQ_MIN_CONTRACTS = 200   # fallback floor when $ conversion isn't available for a symbol —
                              # NOT a $ equivalent to LIQUIDATION_MIN_USD, just noise reduction.
_okx_ct_val_cache = {}       # instId -> (ctVal, ctMult, ctValCcy)
_okx_ct_val_fetched_at = 0

def _okx_fetch_ct_values() -> dict:
    """instId -> (ctVal, ctMult, ctValCcy) for every OKX SWAP instrument, via
    OKX's own public instruments endpoint. True face value per contract =
    ctVal x ctMult, denominated in ctValCcy (the base coin for USDT-margined
    linear swaps, e.g. "BTC" for BTC-USDT-SWAP). Cached for an hour since
    these rarely change. Returns the last known-good cache (possibly empty)
    on any fetch failure instead of raising — callers must handle a miss."""
    global _okx_ct_val_cache, _okx_ct_val_fetched_at
    if _okx_ct_val_cache and time.time() - _okx_ct_val_fetched_at < 3600:
        return _okx_ct_val_cache
    try:
        _headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                                  "(KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"}
        r = requests.get("https://www.okx.com/api/v5/public/instruments",
                          params={"instType": "SWAP"}, headers=_headers, timeout=15).json()
        m = {}
        for it in r.get("data", []):
            inst_id = it.get("instId")
            ct_val  = float(it.get("ctVal", 0) or 0)
            ct_mult = float(it.get("ctMult", 1) or 1)
            ct_ccy  = it.get("ctValCcy", "")
            if inst_id and ct_val > 0:
                m[inst_id] = (ct_val, ct_mult, ct_ccy)
        if m:
            _okx_ct_val_cache = m
            _okx_ct_val_fetched_at = time.time()
            print(f"  [LIQUIDATION-OKX] loaded {len(m)} contract-value multipliers — $ conversion active")
        return _okx_ct_val_cache
    except Exception as e:
        print(f"  [LIQUIDATION-OKX] ctVal fetch failed ({e}) — posting contract counts instead")
        return _okx_ct_val_cache

def _handle_okx_liquidation_msg(raw: str):
    global _last_liq_post_time, latest_news_context
    if not SEND_NEWS or raw == "pong":
        return
    try:
        d = json.loads(raw)
        arg = d.get("arg", {})
        if arg.get("channel") != "liquidation-orders":
            return  # subscribe ack / error event, not liquidation data
        ct_values = _okx_fetch_ct_values()
        for entry in d.get("data", []):
            inst_id = entry.get("instId", "?")             # e.g. "DYDX-USDT-SWAP"
            sym = inst_id.replace("-USDT-SWAP", "USDT").replace("-", "")
            for det in entry.get("details", []):
                pos_side  = det.get("posSide", "?")         # long/short — the position that got liquidated
                bk_px     = float(det.get("bkPx", 0) or 0)  # bankruptcy price
                contracts = float(det.get("sz", 0) or 0)

                ct_info = ct_values.get(inst_id)
                usd = None
                if ct_info and bk_px > 0:
                    ct_val, ct_mult, ct_ccy = ct_info
                    face = contracts * ct_val * ct_mult
                    # ctValCcy is either the quote asset already in $ terms
                    # (rare for USDT-margined swaps, but check anyway) or the
                    # base coin — the common case for *-USDT-SWAP contracts.
                    usd = face if ct_ccy in ("USD", "USDT") else face * bk_px

                if usd is not None:
                    if usd < LIQUIDATION_MIN_USD:
                        continue
                else:
                    if contracts < OKX_LIQ_MIN_CONTRACTS:
                        continue

                now = time.time()
                if now - _last_liq_post_time < LIQUIDATION_POST_COOLDOWN:
                    continue
                if pos_side == "long":
                    impact, emoji, closed = "BEARISH", "🔴", "LONG"
                else:
                    impact, emoji, closed = "BULLISH", "🟢", "SHORT"

                if usd is not None:
                    usd_label = f"{usd/1e6:,.2f}M" if usd >= 1_000_000 else \
                                f"{usd/1e3:,.1f}K" if usd >= 1_000 else f"{usd:,.0f}"
                    title = f"{usd_label} {sym} {closed} liquidated"
                    size_line = f"💰 Size: <code>{contracts:,.0f} contracts</code> (${usd:,.0f})\n"
                else:
                    contracts_label = f"{contracts:,.0f}"
                    title = f"{contracts_label} contracts {sym} {closed} liquidated"
                    size_line = (f"💰 Size: <code>{contracts_label} contracts</code> "
                                 f"⚠️ <i>not $ — multiplier unavailable for this symbol</i>\n")
                msg_text = (
                    f"<b>TRENDING INSIGHT (OKX)</b>\n\n{emoji} <b>{impact}</b>\n"
                    f"<b>{title}</b>\n\n"
                    f"💥 {closed} position force-closed\n"
                    f"{size_line}"
                    f"💵 Bankruptcy Price: <code>{bk_px:,.4g}</code>"
                )
                send_to_tier_channels(msg_text, share_free=False)
                _last_liq_post_time = now
                latest_news_context = ([f"• {impact}: {title}"] + latest_news_context)[:3]
    except Exception as e:
        print(f"  [LIQUIDATION-OKX] parse/post error: {e}")

def _okx_liquidation_ws_loop():
    """Runs forever in a background thread — reconnects automatically on drop.
    OKX's keepalive is different from Bybit's: it's a plain-text "ping" (NOT
    JSON) sent by the CLIENT after a quiet period, with the server replying
    plain-text "pong" — OKX drops the connection if it goes >30s with no
    traffic either way, so the client must proactively ping before that."""
    if not HAS_WEBSOCKET:
        print("  [LIQUIDATION-OKX] websocket-client not installed — feed disabled"); return
    url = "wss://ws.okx.com:8443/ws/v5/public"
    while True:
        try:
            ws = _ws_client.create_connection(url, timeout=20)
            # One subscription with instType=SWAP covers every OKX perpetual —
            # no per-symbol list needed, unlike Bybit.
            ws.send(json.dumps({"op": "subscribe", "args": [{"channel": "liquidation-orders", "instType": "SWAP"}]}))
            print("  [LIQUIDATION-OKX] connected")
            _last_activity = time.time()
            while True:
                try:
                    msg = ws.recv()
                    _last_activity = time.time()
                except Exception as _recv_e:
                    if "timed out" in str(_recv_e).lower():
                        msg = None
                    else:
                        raise
                if time.time() - _last_activity >= 20:
                    ws.send("ping")  # plain text, not JSON — see docstring
                    _last_activity = time.time()
                if msg:
                    _handle_okx_liquidation_msg(msg)
        except Exception as e:
            print(f"  [LIQUIDATION-OKX] connection error: {e} — reconnecting in 10s")
        time.sleep(10)

# --- BINGX WHALE TRADES + ORDER-BOOK TRACKING + LIQUIDATION-HEATMAP ---------
# Added 2026-07-27, per request: (1) whale-sized trade alerts with an
# ESTIMATED liquidation price, (2) live tracking of large resting orders on
# the book (placed/increased/decreased/canceled), (3) an on-demand
# liquidation-heatmap command. All built on BingX (not Binance/Bybit/OKX)
# because it's the one exchange this server has PROVEN reachable — the bot's
# own real trading already runs on BingX's REST API continuously, and this
# reuses that same domain family. Bybit's REST got CloudFront-blocked from
# this server, Binance's WebSocket was fully network-blocked — BingX sidesteps
# repeating either problem, but its WS specifics below (esp. the "m" maker-
# flag meaning and depth-snapshot semantics) come from reading ccxt's BingX
# implementation, not a live test I could run myself — the debug heartbeat in
# each loop exists so the first deploy immediately shows what's working
# instead of guessing blind, same lesson learned from Bybit/OKX earlier today.
#
# IMPORTANT CAVEAT that must stay in every message these produce: none of
# this is a REAL liquidation price or a confirmed "opened a new position" —
# actual leverage/margin per trader is private, no exchange publishes it.
# Liquidation prices shown are ESTIMATES at common leverage tiers, same
# method CoinGlass-style heatmaps use (liq_price = entry * (1 -+ 1/leverage)).

WHALE_TRADE_MIN_USD = 200000     # single-trade notional floor for a "whale trade" alert
WHALE_POST_COOLDOWN = 20         # seconds between whale-trade posts
BOOK_WALL_MIN_USD = 200000       # resting order size floor for order-book tracking
BOOK_WALL_POST_COOLDOWN = 15     # seconds between order-book wall posts
_LIQ_LEVERAGE_TIERS = [10, 25, 50, 75, 100]

_bingx_symbols_cache: list = []
_bingx_symbols_fetched_at = 0

def _bingx_top_symbols(n: int = 40) -> list:
    """Top N BingX USDT-margined perpetuals by 24h quote volume — same
    ticker endpoint (open-api.bingx.com) the scan logic already calls
    successfully, so no new REST reachability risk. Cached for an hour."""
    global _bingx_symbols_cache, _bingx_symbols_fetched_at
    if _bingx_symbols_cache and time.time() - _bingx_symbols_fetched_at < 3600:
        return _bingx_symbols_cache
    try:
        r = requests.get("https://open-api.bingx.com/openApi/swap/v2/quote/ticker", timeout=15).json()
        rows = []
        for t in r.get("data", []):
            sym = t.get("symbol", "")
            if not sym.endswith("-USDT"):
                continue
            vol = float(t.get("quoteVolume", 0) or 0)
            rows.append((vol, sym))
        rows.sort(reverse=True)
        syms = [s for _, s in rows[:n]]
        if syms:
            _bingx_symbols_cache = syms
            _bingx_symbols_fetched_at = time.time()
        return _bingx_symbols_cache or ["BTC-USDT", "ETH-USDT"]
    except Exception as e:
        print(f"  [WHALE] BingX symbol list fetch failed ({e})")
        return _bingx_symbols_cache or ["BTC-USDT", "ETH-USDT"]

def _estimate_liq_prices(entry_price: float, is_long: bool) -> list:
    """ESTIMATED liquidation price at common leverage tiers — see module
    docstring above. Never real data, always an approximation."""
    out = []
    for lev in _LIQ_LEVERAGE_TIERS:
        px = entry_price * (1 - 1/lev) if is_long else entry_price * (1 + 1/lev)
        out.append((lev, px))
    return out

def _bingx_ws_recv(ws):
    """Receives one message from a BingX WS connection. Handles the two
    BingX-specific quirks that are NOT the same as Bybit or OKX: (1) frames
    are GZIP-compressed bytes, need decompressing before use, (2) the server
    proactively sends the literal text "Ping" (after decompression) and
    expects a plain-text "Pong" back — unlike Bybit (JSON, client-initiated)
    or OKX (plain text, but client-initiated). Returns None for a plain
    read timeout, a ping, or anything undecodable — callers only ever see
    real data strings."""
    try:
        raw = ws.recv()
    except Exception as e:
        if "timed out" in str(e).lower():
            return None
        raise
    if isinstance(raw, (bytes, bytearray)):
        try:
            raw = gzip.decompress(raw).decode("utf-8")
        except Exception:
            return None
    if raw == "Ping":
        ws.send("Pong")
        return None
    return raw

# --- Whale trade detector ----------------------------------------------------
_last_whale_post_time = 0
_whale_debug_count = 0
_whale_debug_last_log = 0
_recent_trades: dict = {}  # sym -> [(timestamp, price), ...] — ALL trades, not just whale-sized,
                            # so a book wall filled via several smaller trades still gets matched.

def _record_recent_trade(sym: str, price: float, ts: float):
    lst = _recent_trades.setdefault(sym, [])
    lst.append((ts, price))
    cutoff = ts - 20  # 20s rolling window is plenty — walls disappear and get checked within seconds
    while lst and lst[0][0] < cutoff:
        lst.pop(0)

def _wall_likely_filled(sym: str, wall_price: float, now: float) -> bool:
    """True if a real trade happened at/near wall_price within the last 15s —
    strong signal the wall was consumed by an actual trade (filled) rather
    than pulled by the trader (canceled). Not perfect (a trade could
    coincidentally happen nearby right as an unrelated cancel occurs), but
    far better than the previous unconditional 'canceled or filled'."""
    lst = _recent_trades.get(sym, [])
    tol = max(wall_price * 0.001, 1e-8)  # 0.1% price tolerance
    return any((now - ts) <= 15 and abs(p - wall_price) <= tol for ts, p in lst)

def _handle_whale_trade_msg(raw: str):
    global _last_whale_post_time, _whale_debug_count, _whale_debug_last_log
    if not SEND_NEWS:
        return
    try:
        d = json.loads(raw)
        # TEMP DEBUG — confirm raw trade frames are actually arriving, same
        # pattern used to diagnose Bybit/OKX earlier today. Remove once this
        # is confirmed working end-to-end on the real server.
        _whale_debug_count += 1
        _now_dbg = time.time()
        if _now_dbg - _whale_debug_last_log >= 15:
            print(f"  [WHALE-DEBUG] {_whale_debug_count} raw trade frames seen so far — last: {str(d)[:200]}")
            _whale_debug_last_log = _now_dbg
        if not str(d.get("dataType", "")).endswith("@trade"):
            return
        for item in d.get("data", []):
            sym = item.get("s", "?")
            price = float(item.get("p", 0) or 0)
            qty = float(item.get("q", 0) or 0)
            usd = price * qty
            if price > 0:
                _record_recent_trade(sym, price, time.time())  # every trade, for the fill-check below
            if usd < WHALE_TRADE_MIN_USD or price <= 0:
                continue
            now = time.time()
            if now - _last_whale_post_time < WHALE_POST_COOLDOWN:
                continue
            # "m" = isBuyerMaker, same field/convention as Binance's trade
            # stream (BingX copies this schema) — m=True means the taker
            # side was a SELL (hit a resting buy order); m=False means the
            # taker side was a BUY. Inferred from the standard convention,
            # not independently confirmed against BingX specifically.
            is_buyer_maker = bool(item.get("m", False))
            is_long = not is_buyer_maker
            usd_label = f"{usd/1e6:,.2f}M" if usd >= 1_000_000 else f"{usd/1e3:,.0f}K"
            liq_lines = "\n".join(
                f"  {lev}x → <code>{px:,.6g}</code>" for lev, px in _estimate_liq_prices(price, is_long)
            )
            emoji = "🟢" if is_long else "🔴"
            side_label = "BUY (likely long)" if is_long else "SELL (likely short)"
            msg_text = (
                f"<b>🐋 WHALE TRADE</b>\n\n{emoji} <b>{usd_label} {sym} {side_label}</b>\n\n"
                f"💵 Price: <code>{price:,.6g}</code>\n"
                f"📦 Size: <code>{qty:,.4f}</code> ({sym.replace('USDT','').replace('-','')})\n\n"
                f"⚠️ <i>Single large trade — not confirmed to be a new position (could be closing one), "
                f"and leverage is unknown. Liquidation prices below are ESTIMATES only, assuming isolated "
                f"margin at each tier:</i>\n{liq_lines}"
            )
            send_to_tier_channels(msg_text, share_free=False)
            _last_whale_post_time = now
    except Exception as e:
        print(f"  [WHALE] parse/post error: {e}")

def _bingx_whale_ws_loop():
    """Runs forever in a background thread — reconnects automatically on drop."""
    if not HAS_WEBSOCKET:
        print("  [WHALE] websocket-client not installed — feed disabled"); return
    url = "wss://open-api-swap.bingx.com/swap-market"
    while True:
        try:
            symbols = _bingx_top_symbols()
            ws = _ws_client.create_connection(url, timeout=20)
            for sym in symbols:
                ws.send(json.dumps({"id": _gen_signal_id(), "dataType": f"{sym}@trade", "reqType": "sub"}))
            print(f"  [WHALE] connected ({len(symbols)} symbols)")
            while True:
                msg = _bingx_ws_recv(ws)
                if msg:
                    _handle_whale_trade_msg(msg)
        except Exception as e:
            print(f"  [WHALE] connection error: {e} — reconnecting in 10s")
        time.sleep(10)

# --- Order-book large-order (wall) tracker -----------------------------------
# Tracks each symbol's top price levels across successive depth snapshots and
# reports on a large order's full lifecycle (placed / increased / decreased /
# removed) instead of a one-off "big order spotted" alert — a resting order
# that gets pulled seconds later (classic spoofing) is visible as a REMOVED
# post, which is actually useful signal, not just noise.
_book_wall_state: dict = {}       # sym -> {price: usd_size}
_last_book_wall_post_time = 0
_book_wall_debug_count = 0
_book_wall_debug_last_log = 0

def _handle_bingx_depth_msg(raw: str):
    global _last_book_wall_post_time, _book_wall_debug_count, _book_wall_debug_last_log
    if not SEND_NEWS:
        return
    try:
        d = json.loads(raw)
        _book_wall_debug_count += 1
        _now_dbg = time.time()
        if _now_dbg - _book_wall_debug_last_log >= 15:
            print(f"  [BOOKWALL-DEBUG] {_book_wall_debug_count} raw depth frames seen so far — last: {str(d)[:200]}")
            _book_wall_debug_last_log = _now_dbg
        data_type = str(d.get("dataType", ""))
        if "@depth" not in data_type:
            return
        sym = data_type.split("@")[0]
        book = d.get("data", {})
        bids = book.get("bids", []) or []
        asks = book.get("asks", []) or []

        prev = _book_wall_state.get(sym, {})
        cur = {}
        for side_name, levels in (("BUY", bids), ("SELL", asks)):
            for lvl in levels:
                try:
                    px, qty = float(lvl[0]), float(lvl[1])
                except (ValueError, IndexError):
                    continue
                usd = px * qty
                if usd < BOOK_WALL_MIN_USD:
                    continue
                cur[(side_name, px)] = usd

        now = time.time()
        if now - _last_book_wall_post_time >= BOOK_WALL_POST_COOLDOWN:
            # Compare against the previous snapshot for this symbol —
            # new key = PLACED, missing key = REMOVED (checked against the
            # recent-trade log to guess filled vs canceled), size changed
            # meaningfully = INCREASED/DECREASED.
            for key, usd in cur.items():
                if key not in prev:
                    _post_book_wall(sym, key, usd, "PLACED 🆕")
                    now = _last_book_wall_post_time = time.time()
                    break
                elif usd >= prev[key] * 1.5:
                    _post_book_wall(sym, key, usd, "INCREASED 📈", prev[key])
                    now = _last_book_wall_post_time = time.time()
                    break
                elif usd <= prev[key] * 0.5:
                    _post_book_wall(sym, key, usd, "DECREASED 📉", prev[key])
                    now = _last_book_wall_post_time = time.time()
                    break
            if now == _last_book_wall_post_time:
                pass
            else:
                for key, prev_usd in prev.items():
                    if key not in cur:
                        _, wall_px = key
                        if _wall_likely_filled(sym, wall_px, time.time()):
                            action = "REMOVED ❌ — likely FILLED ✅"
                        else:
                            action = "REMOVED ❌ — likely CANCELED 🚫"
                        _post_book_wall(sym, key, 0, action, prev_usd)
                        break

        _book_wall_state[sym] = cur
    except Exception as e:
        print(f"  [BOOKWALL] parse/post error: {e}")

def _post_book_wall(sym: str, key: tuple, usd: float, action: str, prev_usd: float = None):
    side_name, px = key
    usd_label = f"{usd/1e6:,.2f}M" if usd >= 1_000_000 else f"{usd/1e3:,.0f}K"
    emoji = "🟢" if side_name == "BUY" else "🔴"
    detail = f"💰 Size: <code>{usd_label}</code>\n" if usd > 0 else ""
    if prev_usd:
        prev_label = f"{prev_usd/1e6:,.2f}M" if prev_usd >= 1_000_000 else f"{prev_usd/1e3:,.0f}K"
        detail += f"↩️ Was: <code>{prev_label}</code>\n"
    if "FILLED" in action:
        caveat = "✅ <i>A matching trade happened at/near this price and time — likely genuinely filled, not spoofed.</i>"
    elif "CANCELED" in action:
        caveat = "🚫 <i>No matching trade seen nearby — likely just pulled by the trader (classic spoofing pattern).</i>"
    else:
        caveat = "⚠️ <i>Resting order, not an executed trade — can be canceled anytime (spoofing is common).</i>"
    msg_text = (
        f"<b>📖 ORDER BOOK — {action}</b>\n\n{emoji} <b>{side_name} wall on {sym}</b>\n\n"
        f"💵 Price: <code>{px:,.6g}</code>\n{detail}\n{caveat}"
    )
    send_to_tier_channels(msg_text, share_free=False)

def _bingx_bookwall_ws_loop():
    """Runs forever in a background thread — reconnects automatically on drop."""
    if not HAS_WEBSOCKET:
        print("  [BOOKWALL] websocket-client not installed — feed disabled"); return
    url = "wss://open-api-swap.bingx.com/swap-market"
    while True:
        try:
            symbols = _bingx_top_symbols()
            ws = _ws_client.create_connection(url, timeout=20)
            for sym in symbols:
                ws.send(json.dumps({"id": _gen_signal_id(), "dataType": f"{sym}@depth20", "reqType": "sub"}))
            print(f"  [BOOKWALL] connected ({len(symbols)} symbols)")
            while True:
                msg = _bingx_ws_recv(ws)
                if msg:
                    _handle_bingx_depth_msg(msg)
        except Exception as e:
            print(f"  [BOOKWALL] connection error: {e} — reconnecting in 10s")
        time.sleep(10)

# --- Liquidation heatmap (on-demand estimate, not a push feed) --------------
# Unlike whale trades/liquidations/book walls, open interest doesn't change
# meaningfully minute-to-minute, so this is a COMMAND (/liqmap SYMBOL), not
# a background alert loop — pushing it on a timer would just be noise.
def _build_liq_heatmap_text(symbol: str) -> str:
    sym = symbol.upper().replace("USDT", "").replace("-", "") + "-USDT"
    try:
        r = requests.get("https://open-api.bingx.com/openApi/swap/v2/quote/openInterest",
                          params={"symbol": sym}, timeout=15).json()
        oi_usd = float(r.get("data", {}).get("openInterest", 0) or 0)
        price = get_bingx_price(sym)
        if not price or oi_usd <= 0:
            return f"⚠️ No open interest data for {sym} right now."
    except Exception as e:
        return f"⚠️ Fetch failed for {sym}: {e}"

    lines = [f"<b>🗺 Liquidation Heatmap (estimate) — {sym}</b>",
             f"💵 Price: <code>{price:,.6g}</code>  |  Open Interest: <code>${oi_usd/1e6:,.1f}M</code>", ""]
    lines.append("<i>ESTIMATED pressure zones if this OI were evenly split long/short at each leverage "
                 "tier — NOT real per-position data (no exchange publishes that).</i>")
    lines.append("")
    lines.append("🟢 LONG liquidations cluster near (if price falls to):")
    for lev, px in _estimate_liq_prices(price, is_long=True):
        lines.append(f"  {lev}x → <code>{px:,.6g}</code>")
    lines.append("")
    lines.append("🔴 SHORT liquidations cluster near (if price rises to):")
    for lev, px in _estimate_liq_prices(price, is_long=False):
        lines.append(f"  {lev}x → <code>{px:,.6g}</code>")
    return "\n".join(lines)

# --- CRYPTO PAY (@CryptoBot) — invoices + payment event poll loop -------------
CRYPTO_PAY_BASE_URL = "https://pay.crypt.bot/api"

def _cryptopay_create_invoice(amount_usd: float, payload_dict: dict, description: str = "") -> str:
    """Creates a CryptoBot invoice, returns its pay_url or None on failure.
    payload_dict is echoed back verbatim (as a JSON string) in the webhook
    once paid — that's how api.py's /cryptopay/webhook knows what the payment
    was for and which user, without us needing a separate pending-invoice table."""
    if not CRYPTO_PAY_API_TOKEN:
        print("  [CRYPTOPAY] CRYPTO_PAY_API_TOKEN not set"); return None
    try:
        r = requests.post(f"{CRYPTO_PAY_BASE_URL}/createInvoice",
            headers={"Crypto-Pay-API-Token": CRYPTO_PAY_API_TOKEN},
            json={"asset": "USDT", "amount": f"{amount_usd:.2f}",
                  "description": description or "CLEXER payment",
                  "payload": json.dumps(payload_dict)},
            timeout=15)
        rj = r.json()
        if rj.get("ok"):
            return rj["result"]["pay_url"]
        print(f"  [CRYPTOPAY] createInvoice failed: {rj}")
    except Exception as e:
        print(f"  [CRYPTOPAY] createInvoice error: {e}")
    return None

def _grant_vip(cid: str, days: int = 30):
    """Grants VIP for `days` days from today — mirrors /setvip's exact field
    shape (copytrade.py's handle(), '/setvip <cid> <start> <end>' branch):
    DD.MM.YYYY date strings, tier='vip', vip_grace_notified_at reset to 0.
    Shared by both payment gateways (CryptoBot and Telegram Stars) since the
    grant itself doesn't care how the user paid."""
    u = ct._db.get(str(cid)) or ct._default_user(cid)
    start = now_ist(); end = start + timedelta(days=days)
    u["tier"] = "vip"
    u["vip_start"] = start.strftime("%d.%m.%Y")
    u["vip_end"] = end.strftime("%d.%m.%Y")
    u["vip_grace_notified_at"] = 0
    ct._set(cid, u)

# Tracks each unpaid Stars invoice's own message_id, keyed by (cid, type, sig_id) —
# so once successful_payment arrives, the invoice card itself can be deleted
# instead of sitting in the chat forever after payment. sig_id is "" for
# vip/topup payloads (only one field-set that can collide on cid+type there).
_pending_star_invoices: dict = {}

def _stars_send_invoice(chat_id, title: str, description: str, payload_dict: dict, amount_usd: float) -> bool:
    """Sends a Telegram Stars (XTR) invoice — Telegram renders its own native
    pay button right in the chat, no external checkout page and no provider
    token needed. payload_dict is echoed back verbatim as the invoice_payload
    on the resulting successful_payment update (see command_listener), the
    same role CryptoBot's invoice payload plays for _poll_payment_events."""
    stars = max(1, round(amount_usd * STARS_PER_USD))
    try:
        r = requests.post(f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendInvoice",
            json={"chat_id": chat_id, "title": title[:32], "description": description[:255],
                  "payload": json.dumps(payload_dict), "provider_token": "", "currency": "XTR",
                  "prices": [{"label": title[:32], "amount": stars}]}, timeout=15)
        rj = r.json()
        if rj.get("ok"):
            _mid = rj.get("result", {}).get("message_id")
            if _mid:
                _key = (str(chat_id), payload_dict.get("type"), payload_dict.get("sig_id", ""))
                _pending_star_invoices[_key] = _mid
            return True
        print(f"  [STARS] sendInvoice failed: {rj}")
    except Exception as e:
        print(f"  [STARS] sendInvoice error: {e}")
    return False

def _poll_payment_events():
    """Runs forever — every 30s, applies any unprocessed CryptoBot payment
    events (wallet topup / VIP purchase) via ct._get/_set. Safe against races:
    this is the one long-running process that owns ct._db in memory, and the
    webhook (api.py, a separate stateless process) only ever INSERTs rows into
    payment_events — never touches the user DB directly. See api.py's
    /cryptopay/webhook and the payment_events table for the other half."""
    if not CLEXER_API_URL:
        print("  [PAYMENT EVENTS] CLEXER_API_URL not set — poll loop disabled"); return
    while True:
        try:
            time.sleep(30)
            hdrs = {"X-Push-Secret": PUSH_STATE_SECRET} if PUSH_STATE_SECRET else {}
            r = requests.get(f"{CLEXER_API_URL}/payment_events", params={"processed": "false"}, headers=hdrs, timeout=10)
            if not r.ok:
                continue
            for ev in r.json().get("events", []):
                try:
                    cid = ev["cid"]; etype = ev["event_type"]; amount = float(ev["amount"])
                    meta = ev.get("meta") or {}
                    if etype == "topup":
                        u = ct._db.get(str(cid)) or ct._default_user(cid)
                        u["wallet_balance"] = round(u.get("wallet_balance", 0) + amount, 2)
                        ct._set(cid, u)
                        send_to_user(cid, f"💰 <b>Wallet credited</b>: +${amount:,.2f}\n\nNew balance: <b>${u['wallet_balance']:,.2f}</b>")
                    elif etype == "vip":
                        _grant_vip(cid, days=30)
                        send_to_user(cid, f"🎉 <b>VIP Activated!</b>\n\nPaid: ${amount:,.2f} · 30 days\n\nTap ⭐ VIP Channel in /help to get access.")
                    elif etype == "virtual_toggle":
                        ct.virtual_set_enabled(cid, bool(meta.get("enabled")))
                    elif etype == "virtual_settings":
                        ct.virtual_set_settings(cid, balance=meta.get("balance"), leverage=meta.get("leverage"))
                    requests.post(f"{CLEXER_API_URL}/payment_events/{ev['id']}/ack", headers=hdrs, timeout=10)
                except Exception as e:
                    print(f"  [PAYMENT EVENTS] apply error for event {ev.get('id')}: {e}")
        except Exception as e:
            print(f"  [PAYMENT EVENTS] poll error: {e}")

def check_news(force=False):
    """Kept for /latestnews compatibility — the liquidation feed posts live as
    events happen (see _liquidation_ws_loop), so there's nothing to "fetch on
    demand" the way the old RSS/Whale-Alert polling model worked. Just reports
    feed status instead."""
    if not force:
        return
    if not HAS_WEBSOCKET:
        send_admin("⚠️ websocket-client not installed — liquidation feed can't run."); return
    send_admin("ℹ️ Liquidation feed runs continuously in the background — nothing to fetch on demand. "
               f"Posts big liquidations (≥ ${LIQUIDATION_MIN_USD:,.0f}) live as they happen when News is ON.")

# --- /tvstatus ----------------------------------------------------------------
def cmd_tvstatus(chat_id):
    if not TV_BRIDGE_URL:
        send_reply(chat_id, "<b>TV Status</b>\n\nTV_BRIDGE_URL not set.\nRunning on <b>Binance</b>."); return
    send_reply(chat_id, f"Checking...\n<code>{TV_BRIDGE_URL}</code>")
    now = time.time(); health = tv_ping()
    if not health:
        ls = tv_bridge_state.get("last_seen",0)
        since = f"{int((now-ls)//60)}m ago" if ls else "never"
        send_reply(chat_id, f"<b>TV Status</b>\n\n🔴 Bridge OFFLINE\nLast seen: {since}\n\nUsing: <b>Binance</b>"); return
    tv_bridge_state.update({"online":True,"last_seen":now,"cdp_ok":health.get("cdp_connected",False),
        "tv_version":health.get("tv_version",""),"cached_intervals":health.get("cached_intervals",[])})
    cdp_ok = health.get("cdp_connected",False); tv_version = health.get("tv_version","?")
    tv_symbol = health.get("symbol",SYMBOL); uptime = health.get("uptime_seconds",0)
    cached_ivs = health.get("cached_intervals",[])
    tk = tv_get_ticker(); price_ok = tk and tk.get("price",0)>0; price_val = tk["price"] if price_ok else 0
    df = tv_get_candles("1h",10); candles_ok = df is not None and len(df)>0
    def tick(ok): return "🟢" if ok else "🔴"
    overall = "<b>ALL SYSTEMS GO</b>" if (cdp_ok and price_ok and candles_ok) else "<b>PARTIAL</b>"
    uptime_str = f"{uptime//3600:.0f}h {(uptime%3600)//60:.0f}m" if uptime>=3600 else f"{uptime//60:.0f}m {uptime%60:.0f}s"
    send_reply(chat_id, f"<b>TV Status</b>\n\n{overall}\n\n"
        f"{tick(True)} Bridge reachable\n{tick(cdp_ok)} TradingView connected\n"
        f"{tick(price_ok)} Price feed" + (f" ({price_val:,.2f})" if price_ok else "") + "\n"
        f"{tick(candles_ok)} Candles" + (f" ({len(df)} bars 1H)" if candles_ok else "") + "\n\n"
        f"Cached: {', '.join(cached_ivs) if cached_ivs else 'none'}\n"
        f"TV: <code>{tv_version}</code> | Symbol: <code>{tv_symbol}</code>\n"
        f"Uptime: <b>{uptime_str}</b>\n\n{ist_str()}")

