# grid (not replacing it), same 17 minutes for all four kinds (scan1/scan2/
# demo1/demo2), fires simultaneously across all of them. Starts every slot
# as nonspecial (see _ai_category) so nothing here reaches VIP/Free or
# copytrade until a specific (hour,minute) proves itself and gets promoted
# to verified by the existing auto-promote system — same win-rate/1:3-
# blacklist rules as the rest of the regular grid, just denser.
_DENSE_GRID_MINUTES = [3, 7, 9, 13, 15, 19, 23, 27, 29, 33, 37, 41, 45, 48, 52, 56, 59]

